-- ============================================================================
-- Scalable Multi-tenant CRM Database for Supabase / PostgreSQL 15+
-- Version: 1.0.1-supabase
-- Updated for Supabase: 2026-07-29
--
-- Design goals:
--   * Shared-table multi-tenancy with tenant-first composite keys.
--   * PostgreSQL Row-Level Security (RLS) using transaction-local context.
--   * UUIDv4 primary identifiers generated by PostgreSQL gen_random_uuid().
--   * B2B and B2C CRM: accounts, contacts, leads, opportunities, activities.
--   * Sales, catalog, marketing, customer service, privacy, audit, integration.
--   * Time-partitioned append/event tables and tenant-first operational indexes.
--
-- Runtime requirement:
--   At the start of each application transaction, set tenant context:
--     BEGIN;
--     SELECT platform.set_request_context(
--       'TENANT_UUID'::uuid,
--       'USER_UUID'::uuid,
--       'REQUEST_UUID'::uuid
--     );
--     -- application queries
--     COMMIT;
--
-- Security note:
--   End users must never connect directly to PostgreSQL. The trusted backend
--   validates tenant membership before setting app.tenant_id/app.user_id.
--   Superusers and roles with BYPASSRLS bypass RLS and must be tightly controlled.
-- Supabase compatibility notes:
--   * Supabase projects commonly run PostgreSQL 15 or 17, where uuidv7() is
--     unavailable. This script uses gen_random_uuid() instead.
--   * RLS in this version uses transaction-local app.tenant_id/app.user_id and
--     is intended for a trusted backend/database connection. It does not yet
--     use auth.uid() for direct browser access through the Supabase Data API.
--   * Custom schemas must be explicitly exposed in Supabase API settings before
--     they can be queried through supabase-js/PostgREST.
-- ============================================================================

BEGIN;

SET TIME ZONE 'UTC';
SET client_min_messages TO warning;

CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE SCHEMA IF NOT EXISTS common;
CREATE SCHEMA IF NOT EXISTS platform;
CREATE SCHEMA IF NOT EXISTS crm;
CREATE SCHEMA IF NOT EXISTS catalog;
CREATE SCHEMA IF NOT EXISTS sales;
CREATE SCHEMA IF NOT EXISTS marketing;
CREATE SCHEMA IF NOT EXISTS service;
CREATE SCHEMA IF NOT EXISTS privacy;
CREATE SCHEMA IF NOT EXISTS integration;
CREATE SCHEMA IF NOT EXISTS audit;

COMMENT ON SCHEMA common IS 'Shared domains, functions, and database utilities.';
COMMENT ON SCHEMA platform IS 'Tenant, identity, team, role, and permission data.';
COMMENT ON SCHEMA crm IS 'Core CRM customer, lead, opportunity, and activity data.';
COMMENT ON SCHEMA catalog IS 'Products, price books, and price book entries.';
COMMENT ON SCHEMA sales IS 'Quotes, orders, contracts, and immutable line snapshots.';
COMMENT ON SCHEMA marketing IS 'Campaigns and campaign membership.';
COMMENT ON SCHEMA service IS 'Customer service tickets, SLAs, and event history.';
COMMENT ON SCHEMA privacy IS 'Consent, retention, and data-subject request workflows.';
COMMENT ON SCHEMA integration IS 'Outbox, webhooks, idempotency, and import jobs.';
COMMENT ON SCHEMA audit IS 'Change audit and sensitive-data access trails.';

-- --------------------------------------------------------------------------
-- Common domains
-- --------------------------------------------------------------------------

CREATE DOMAIN common.country_code AS varchar(2)
    CHECK (VALUE ~ '^[A-Z]{2}$');

CREATE DOMAIN common.currency_code AS varchar(3)
    CHECK (VALUE ~ '^[A-Z]{3}$');

CREATE DOMAIN common.language_code AS varchar(10)
    CHECK (VALUE ~ '^[A-Za-z]{2,3}(-[A-Za-z0-9]{2,8})*$');

CREATE DOMAIN common.phone_e164 AS text
    CHECK (VALUE ~ '^\+[1-9][0-9]{1,14}$');

CREATE DOMAIN common.money_amount AS numeric(20,6);

CREATE DOMAIN common.nonnegative_amount AS numeric(20,6)
    CHECK (VALUE >= 0);

CREATE DOMAIN common.positive_quantity AS numeric(20,6)
    CHECK (VALUE > 0);

CREATE DOMAIN common.percentage AS numeric(5,2)
    CHECK (VALUE >= 0 AND VALUE <= 100);

CREATE DOMAIN common.nonempty_text AS text
    CHECK (btrim(VALUE) <> '');

-- --------------------------------------------------------------------------
-- Request context and common trigger helpers
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION platform.current_tenant_id()
RETURNS uuid
LANGUAGE sql
STABLE
PARALLEL SAFE
AS $$
SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid
$$;

CREATE OR REPLACE FUNCTION platform.current_actor_user_id()
RETURNS uuid
LANGUAGE sql
STABLE
PARALLEL SAFE
AS $$
SELECT NULLIF(current_setting('app.user_id', true), '')::uuid
$$;

CREATE OR REPLACE FUNCTION platform.current_request_id()
RETURNS uuid
LANGUAGE sql
STABLE
PARALLEL SAFE
AS $$
SELECT NULLIF(current_setting('app.request_id', true), '')::uuid
$$;

CREATE OR REPLACE FUNCTION platform.set_request_context(
  p_tenant_id uuid,
  p_user_id uuid DEFAULT NULL,
  p_request_id uuid DEFAULT NULL
)
RETURNS void
LANGUAGE plpgsql
VOLATILE
SET search_path = pg_catalog, platform
AS $$
BEGIN
  PERFORM set_config('app.tenant_id', p_tenant_id::text, true);
  PERFORM set_config('app.user_id', COALESCE(p_user_id::text, ''), true);
  PERFORM set_config('app.request_id', COALESCE(p_request_id::text, ''), true);
END;
$$;

CREATE OR REPLACE FUNCTION common.touch_row()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, common
AS $$
BEGIN
  NEW.updated_at := clock_timestamp();
  NEW.version := OLD.version + 1;
  NEW.updated_by := COALESCE(
    platform.current_actor_user_id(),
    NEW.updated_by,
    OLD.updated_by
  );
RETURN NEW;
END;
$$;

-- --------------------------------------------------------------------------
-- Platform: tenants, identities, teams, RBAC
-- --------------------------------------------------------------------------

CREATE TABLE platform.tenants (
                                  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
                                  tenant_code citext NOT NULL,
                                  legal_name common.nonempty_text NOT NULL,
                                  display_name common.nonempty_text NOT NULL,
                                  default_currency_code common.currency_code NOT NULL,
                                  default_country_code common.country_code NOT NULL,
                                  default_language_code common.language_code NOT NULL DEFAULT 'en',
                                  default_timezone text NOT NULL DEFAULT 'UTC',
                                  data_region text,
                                  status text NOT NULL DEFAULT 'ACTIVE'
                                      CHECK (status IN ('TRIAL', 'ACTIVE', 'SUSPENDED', 'CLOSED')),
                                  plan_code text,
                                  retention_days integer CHECK (retention_days IS NULL OR retention_days >= 0),
                                  metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  created_by uuid,
                                  updated_by uuid,
                                  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                  CONSTRAINT uq_tenants_tenant_code UNIQUE (tenant_code)
);

CREATE TABLE platform.users (
                                id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
                                email citext NOT NULL,
                                display_name common.nonempty_text NOT NULL,
                                given_name text,
                                family_name text,
                                preferred_language_code common.language_code,
                                external_subject text,
                                identity_provider text,
                                status text NOT NULL DEFAULT 'ACTIVE'
                                    CHECK (status IN ('INVITED', 'ACTIVE', 'LOCKED', 'DISABLED')),
                                last_login_at timestamptz,
                                metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                created_by uuid,
                                updated_by uuid,
                                version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                CONSTRAINT uq_users_email UNIQUE (email),
                                CONSTRAINT uq_users_external_identity UNIQUE NULLS NOT DISTINCT
                                    (identity_provider, external_subject)
);

CREATE TABLE platform.tenant_memberships (
                                             tenant_id uuid NOT NULL,
                                             user_id uuid NOT NULL,
                                             membership_status text NOT NULL DEFAULT 'ACTIVE'
                                                 CHECK (membership_status IN ('INVITED', 'ACTIVE', 'SUSPENDED', 'REMOVED')),
                                             employee_reference text,
                                             job_title text,
                                             locale common.language_code,
                                             timezone text,
                                             joined_at timestamptz,
                                             removed_at timestamptz,
                                             is_tenant_admin boolean NOT NULL DEFAULT false,
                                             metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                             created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                             updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                             created_by uuid,
                                             updated_by uuid,
                                             version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                             PRIMARY KEY (tenant_id, user_id),
                                             FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                             FOREIGN KEY (user_id) REFERENCES platform.users(id) ON DELETE RESTRICT,
                                             CHECK (removed_at IS NULL OR membership_status = 'REMOVED')
);

CREATE TABLE platform.teams (
                                tenant_id uuid NOT NULL,
                                id uuid NOT NULL DEFAULT gen_random_uuid(),
                                name common.nonempty_text NOT NULL,
                                description text,
                                parent_team_id uuid,
                                manager_user_id uuid,
                                status text NOT NULL DEFAULT 'ACTIVE'
                                    CHECK (status IN ('ACTIVE', 'INACTIVE')),
                                created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                created_by uuid,
                                updated_by uuid,
                                deleted_at timestamptz,
                                deleted_by uuid,
                                version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                PRIMARY KEY (tenant_id, id),
                                FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                FOREIGN KEY (tenant_id, parent_team_id)
                                    REFERENCES platform.teams(tenant_id, id) ON DELETE SET NULL (parent_team_id),
                                FOREIGN KEY (tenant_id, manager_user_id)
                                    REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (manager_user_id)
);

CREATE UNIQUE INDEX uq_teams_active_name
    ON platform.teams (tenant_id, lower(name::text))
    WHERE deleted_at IS NULL;

CREATE TABLE platform.team_members (
                                       tenant_id uuid NOT NULL,
                                       team_id uuid NOT NULL,
                                       user_id uuid NOT NULL,
                                       member_role text,
                                       is_primary boolean NOT NULL DEFAULT false,
                                       joined_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                       left_at timestamptz,
                                       created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                       created_by uuid,
                                       PRIMARY KEY (tenant_id, team_id, user_id),
                                       FOREIGN KEY (tenant_id, team_id)
                                           REFERENCES platform.teams(tenant_id, id) ON DELETE CASCADE,
                                       FOREIGN KEY (tenant_id, user_id)
                                           REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE CASCADE,
                                       CHECK (left_at IS NULL OR left_at >= joined_at)
);

CREATE UNIQUE INDEX uq_team_members_one_primary_team
    ON platform.team_members (tenant_id, user_id)
    WHERE is_primary AND left_at IS NULL;

CREATE TABLE platform.permissions (
                                      permission_code text PRIMARY KEY,
                                      description common.nonempty_text NOT NULL,
                                      module_code text NOT NULL,
                                      risk_level text NOT NULL DEFAULT 'NORMAL'
                                          CHECK (risk_level IN ('NORMAL', 'SENSITIVE', 'PRIVILEGED')),
                                      created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE platform.roles (
                                tenant_id uuid NOT NULL,
                                id uuid NOT NULL DEFAULT gen_random_uuid(),
                                role_code text NOT NULL,
                                name common.nonempty_text NOT NULL,
                                description text,
                                is_system boolean NOT NULL DEFAULT false,
                                status text NOT NULL DEFAULT 'ACTIVE'
                                    CHECK (status IN ('ACTIVE', 'INACTIVE')),
                                created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                created_by uuid,
                                updated_by uuid,
                                deleted_at timestamptz,
                                deleted_by uuid,
                                version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                PRIMARY KEY (tenant_id, id),
                                FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX uq_roles_active_code
    ON platform.roles (tenant_id, lower(role_code))
    WHERE deleted_at IS NULL;

CREATE TABLE platform.role_permissions (
                                           tenant_id uuid NOT NULL,
                                           role_id uuid NOT NULL,
                                           permission_code text NOT NULL,
                                           granted_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                           granted_by uuid,
                                           PRIMARY KEY (tenant_id, role_id, permission_code),
                                           FOREIGN KEY (tenant_id, role_id)
                                               REFERENCES platform.roles(tenant_id, id) ON DELETE CASCADE,
                                           FOREIGN KEY (permission_code)
                                               REFERENCES platform.permissions(permission_code) ON DELETE CASCADE
);

CREATE TABLE platform.user_roles (
                                     tenant_id uuid NOT NULL,
                                     user_id uuid NOT NULL,
                                     role_id uuid NOT NULL,
                                     valid_from timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     valid_to timestamptz,
                                     assigned_by uuid,
                                     created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     PRIMARY KEY (tenant_id, user_id, role_id),
                                     FOREIGN KEY (tenant_id, user_id)
                                         REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE CASCADE,
                                     FOREIGN KEY (tenant_id, role_id)
                                         REFERENCES platform.roles(tenant_id, id) ON DELETE CASCADE,
                                     CHECK (valid_to IS NULL OR valid_to > valid_from)
);

CREATE TABLE platform.role_data_scopes (
                                           tenant_id uuid NOT NULL,
                                           id uuid NOT NULL DEFAULT gen_random_uuid(),
                                           role_id uuid NOT NULL,
                                           entity_type text NOT NULL,
                                           scope_type text NOT NULL
                                               CHECK (scope_type IN ('OWN', 'TEAM', 'TEAM_TREE', 'TENANT')),
                                           team_id uuid,
                                           created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                           created_by uuid,
                                           PRIMARY KEY (tenant_id, id),
                                           FOREIGN KEY (tenant_id, role_id)
                                               REFERENCES platform.roles(tenant_id, id) ON DELETE CASCADE,
                                           FOREIGN KEY (tenant_id, team_id)
                                               REFERENCES platform.teams(tenant_id, id) ON DELETE CASCADE,
                                           CHECK ((scope_type IN ('OWN', 'TENANT') AND team_id IS NULL)
                                               OR (scope_type IN ('TEAM', 'TEAM_TREE')))
);

CREATE TABLE platform.tenant_settings (
                                          tenant_id uuid NOT NULL,
                                          setting_key text NOT NULL,
                                          setting_value jsonb NOT NULL,
                                          is_secret_reference boolean NOT NULL DEFAULT false,
                                          updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                          updated_by uuid,
                                          version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                          PRIMARY KEY (tenant_id, setting_key),
                                          FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE
);

CREATE TABLE platform.document_counters (
                                            tenant_id uuid NOT NULL,
                                            counter_key text NOT NULL,
                                            current_value bigint NOT NULL DEFAULT 0 CHECK (current_value >= 0),
                                            updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            PRIMARY KEY (tenant_id, counter_key),
                                            FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE
);

CREATE OR REPLACE FUNCTION platform.next_counter_value(p_counter_key text)
RETURNS bigint
LANGUAGE sql
VOLATILE
SET search_path = pg_catalog, platform
AS $$
  INSERT INTO platform.document_counters (tenant_id, counter_key, current_value)
  VALUES (platform.current_tenant_id(), p_counter_key, 1)
  ON CONFLICT (tenant_id, counter_key)
  DO UPDATE SET
    current_value = platform.document_counters.current_value + 1,
                updated_at = clock_timestamp()
                RETURNING current_value
                $$;

CREATE INDEX idx_tenant_memberships_user
    ON platform.tenant_memberships (user_id, membership_status);
CREATE INDEX idx_team_members_user
    ON platform.team_members (tenant_id, user_id) WHERE left_at IS NULL;
CREATE INDEX idx_user_roles_active
    ON platform.user_roles (tenant_id, user_id, valid_from, valid_to);
CREATE INDEX idx_role_permissions_permission
    ON platform.role_permissions (tenant_id, permission_code, role_id);

