-- --------------------------------------------------------------------------
-- CRM core configuration
-- --------------------------------------------------------------------------

CREATE TABLE crm.lead_sources (
                                  tenant_id uuid NOT NULL,
                                  id uuid NOT NULL DEFAULT gen_random_uuid(),
                                  source_code text NOT NULL,
                                  name common.nonempty_text NOT NULL,
                                  description text,
                                  is_active boolean NOT NULL DEFAULT true,
                                  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  created_by uuid,
                                  updated_by uuid,
                                  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                  PRIMARY KEY (tenant_id, id),
                                  FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                  UNIQUE (tenant_id, source_code)
);

CREATE TABLE crm.lead_statuses (
                                   tenant_id uuid NOT NULL,
                                   id uuid NOT NULL DEFAULT gen_random_uuid(),
                                   status_code text NOT NULL,
                                   name common.nonempty_text NOT NULL,
                                   status_category text NOT NULL
                                       CHECK (status_category IN ('OPEN', 'QUALIFIED', 'DISQUALIFIED', 'CONVERTED')),
                                   display_order integer NOT NULL DEFAULT 0,
                                   is_default boolean NOT NULL DEFAULT false,
                                   is_terminal boolean NOT NULL DEFAULT false,
                                   is_active boolean NOT NULL DEFAULT true,
                                   created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                   updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                   created_by uuid,
                                   updated_by uuid,
                                   version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                   PRIMARY KEY (tenant_id, id),
                                   FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                   UNIQUE (tenant_id, status_code)
);

CREATE UNIQUE INDEX uq_lead_statuses_one_default
    ON crm.lead_statuses (tenant_id)
    WHERE is_default AND is_active;

CREATE TABLE crm.opportunity_lost_reasons (
                                              tenant_id uuid NOT NULL,
                                              id uuid NOT NULL DEFAULT gen_random_uuid(),
                                              reason_code text NOT NULL,
                                              name common.nonempty_text NOT NULL,
                                              description text,
                                              is_active boolean NOT NULL DEFAULT true,
                                              created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                              updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                              created_by uuid,
                                              updated_by uuid,
                                              version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                              PRIMARY KEY (tenant_id, id),
                                              FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                              UNIQUE (tenant_id, reason_code)
);

-- --------------------------------------------------------------------------
-- Accounts, contacts, communication channels, addresses
-- --------------------------------------------------------------------------

CREATE TABLE crm.accounts (
                              tenant_id uuid NOT NULL,
                              id uuid NOT NULL DEFAULT gen_random_uuid(),
                              account_number text NOT NULL,
                              account_type text NOT NULL DEFAULT 'ORGANIZATION'
                                  CHECK (account_type IN ('ORGANIZATION', 'PERSON', 'PARTNER', 'RESELLER', 'SUPPLIER')),
                              legal_name text,
                              display_name common.nonempty_text NOT NULL,
                              parent_account_id uuid,
                              owner_user_id uuid,
                              owner_team_id uuid,
                              lifecycle_stage text NOT NULL DEFAULT 'PROSPECT'
                                  CHECK (lifecycle_stage IN ('PROSPECT', 'QUALIFIED', 'CUSTOMER', 'CHURNED', 'INACTIVE')),
                              industry_code text,
                              tax_identifier text,
                              registration_number text,
                              website text,
                              annual_revenue common.nonnegative_amount,
                              revenue_currency_code common.currency_code,
                              employee_count integer CHECK (employee_count IS NULL OR employee_count >= 0),
                              source_id uuid,
                              description text,
                              preferred_language_code common.language_code,
                              do_not_contact boolean NOT NULL DEFAULT false,
                              custom_summary jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(custom_summary) = 'object'),
                              search_vector tsvector GENERATED ALWAYS AS (
                                  to_tsvector(
                                          'simple'::regconfig,
                                          coalesce(account_number, '') || ' ' ||
                                          coalesce(display_name::text, '') || ' ' ||
                                          coalesce(legal_name, '') || ' ' ||
                                          coalesce(tax_identifier, '') || ' ' ||
                                          coalesce(registration_number, '')
                                  )
                                  ) STORED,
                              created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                              updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                              created_by uuid,
                              updated_by uuid,
                              deleted_at timestamptz,
                              deleted_by uuid,
                              version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                              PRIMARY KEY (tenant_id, id),
                              FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                              FOREIGN KEY (tenant_id, parent_account_id)
                                  REFERENCES crm.accounts(tenant_id, id) ON DELETE SET NULL (parent_account_id),
                              FOREIGN KEY (tenant_id, owner_user_id)
                                  REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                              FOREIGN KEY (tenant_id, owner_team_id)
                                  REFERENCES platform.teams(tenant_id, id) ON DELETE SET NULL (owner_team_id),
                              FOREIGN KEY (tenant_id, source_id)
                                  REFERENCES crm.lead_sources(tenant_id, id) ON DELETE SET NULL (source_id),
                              CHECK (annual_revenue IS NULL OR revenue_currency_code IS NOT NULL)
);

CREATE UNIQUE INDEX uq_accounts_active_number
    ON crm.accounts (tenant_id, account_number)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_accounts_owner_stage
    ON crm.accounts (tenant_id, owner_user_id, lifecycle_stage)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_accounts_parent
    ON crm.accounts (tenant_id, parent_account_id)
    WHERE deleted_at IS NULL AND parent_account_id IS NOT NULL;
CREATE INDEX idx_accounts_display_name_trgm
    ON crm.accounts USING gin (display_name gin_trgm_ops)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_accounts_search
    ON crm.accounts USING gin (search_vector)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_accounts_updated
    ON crm.accounts (tenant_id, updated_at DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE crm.account_relationships (
                                           tenant_id uuid NOT NULL,
                                           id uuid NOT NULL DEFAULT gen_random_uuid(),
                                           account_id uuid NOT NULL,
                                           related_account_id uuid NOT NULL,
                                           relationship_type text NOT NULL,
                                           valid_from date,
                                           valid_to date,
                                           description text,
                                           created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                           created_by uuid,
                                           PRIMARY KEY (tenant_id, id),
                                           FOREIGN KEY (tenant_id, account_id)
                                               REFERENCES crm.accounts(tenant_id, id) ON DELETE CASCADE,
                                           FOREIGN KEY (tenant_id, related_account_id)
                                               REFERENCES crm.accounts(tenant_id, id) ON DELETE CASCADE,
                                           UNIQUE (tenant_id, account_id, related_account_id, relationship_type),
                                           CHECK (account_id <> related_account_id),
                                           CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);

CREATE TABLE crm.contacts (
                              tenant_id uuid NOT NULL,
                              id uuid NOT NULL DEFAULT gen_random_uuid(),
                              contact_number text NOT NULL,
                              account_id uuid,
                              owner_user_id uuid,
                              owner_team_id uuid,
                              honorific text,
                              given_name text,
                              middle_name text,
                              family_name text,
                              display_name common.nonempty_text NOT NULL,
                              job_title text,
                              department text,
                              preferred_language_code common.language_code,
                              preferred_contact_channel text
                                  CHECK (preferred_contact_channel IS NULL OR preferred_contact_channel IN
                                                                              ('EMAIL', 'PHONE', 'MOBILE', 'SMS', 'WHATSAPP', 'OTHER')),
                              lifecycle_stage text NOT NULL DEFAULT 'PROSPECT'
                                  CHECK (lifecycle_stage IN ('PROSPECT', 'QUALIFIED', 'CUSTOMER', 'CHURNED', 'INACTIVE')),
                              date_of_birth date,
                              do_not_contact boolean NOT NULL DEFAULT false,
                              description text,
                              search_vector tsvector GENERATED ALWAYS AS (
                                  to_tsvector(
                                          'simple'::regconfig,
                                          coalesce(contact_number, '') || ' ' ||
                                          coalesce(display_name::text, '') || ' ' ||
                                          coalesce(given_name, '') || ' ' ||
                                          coalesce(middle_name, '') || ' ' ||
                                          coalesce(family_name, '') || ' ' ||
                                          coalesce(job_title, '') || ' ' ||
                                          coalesce(department, '')
                                  )
                                  ) STORED,
                              created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                              updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                              created_by uuid,
                              updated_by uuid,
                              deleted_at timestamptz,
                              deleted_by uuid,
                              version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                              PRIMARY KEY (tenant_id, id),
                              FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                              FOREIGN KEY (tenant_id, account_id)
                                  REFERENCES crm.accounts(tenant_id, id) ON DELETE SET NULL (account_id),
                              FOREIGN KEY (tenant_id, owner_user_id)
                                  REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                              FOREIGN KEY (tenant_id, owner_team_id)
                                  REFERENCES platform.teams(tenant_id, id) ON DELETE SET NULL (owner_team_id)
);

CREATE UNIQUE INDEX uq_contacts_active_number
    ON crm.contacts (tenant_id, contact_number)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_contacts_account
    ON crm.contacts (tenant_id, account_id)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_contacts_owner_stage
    ON crm.contacts (tenant_id, owner_user_id, lifecycle_stage)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_contacts_display_name_trgm
    ON crm.contacts USING gin (display_name gin_trgm_ops)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_contacts_search
    ON crm.contacts USING gin (search_vector)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_contacts_updated
    ON crm.contacts (tenant_id, updated_at DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE crm.communication_channels (
                                            tenant_id uuid NOT NULL,
                                            id uuid NOT NULL DEFAULT gen_random_uuid(),
                                            account_id uuid,
                                            contact_id uuid,
                                            channel_type text NOT NULL
                                                CHECK (channel_type IN ('EMAIL', 'PHONE', 'MOBILE', 'SMS', 'WHATSAPP', 'LINKEDIN', 'OTHER')),
                                            raw_value common.nonempty_text NOT NULL,
                                            normalized_value text,
                                            label text,
                                            is_primary boolean NOT NULL DEFAULT false,
                                            is_verified boolean NOT NULL DEFAULT false,
                                            verified_at timestamptz,
                                            do_not_use boolean NOT NULL DEFAULT false,
                                            metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                            created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            created_by uuid,
                                            updated_by uuid,
                                            deleted_at timestamptz,
                                            deleted_by uuid,
                                            version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                            PRIMARY KEY (tenant_id, id),
                                            FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                            FOREIGN KEY (tenant_id, account_id)
                                                REFERENCES crm.accounts(tenant_id, id) ON DELETE CASCADE,
                                            FOREIGN KEY (tenant_id, contact_id)
                                                REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE,
                                            CHECK (num_nonnulls(account_id, contact_id) = 1),
                                            CHECK (verified_at IS NULL OR is_verified),
                                            CHECK (channel_type <> 'EMAIL' OR position('@' IN raw_value::text) > 1),
                                            CHECK (channel_type NOT IN ('PHONE', 'MOBILE', 'SMS', 'WHATSAPP')
                                                OR normalized_value IS NULL
                                                OR normalized_value ~ '^\+[1-9][0-9]{1,14}$')
    );

CREATE INDEX idx_channels_account
    ON crm.communication_channels (tenant_id, account_id, channel_type)
    WHERE deleted_at IS NULL AND account_id IS NOT NULL;
CREATE INDEX idx_channels_contact
    ON crm.communication_channels (tenant_id, contact_id, channel_type)
    WHERE deleted_at IS NULL AND contact_id IS NOT NULL;
CREATE INDEX idx_channels_normalized
    ON crm.communication_channels (tenant_id, channel_type, normalized_value)
    WHERE deleted_at IS NULL AND normalized_value IS NOT NULL;
CREATE UNIQUE INDEX uq_channels_primary_account_type
    ON crm.communication_channels (tenant_id, account_id, channel_type)
    WHERE deleted_at IS NULL AND account_id IS NOT NULL AND is_primary;
CREATE UNIQUE INDEX uq_channels_primary_contact_type
    ON crm.communication_channels (tenant_id, contact_id, channel_type)
    WHERE deleted_at IS NULL AND contact_id IS NOT NULL AND is_primary;

CREATE TABLE crm.addresses (
                               tenant_id uuid NOT NULL,
                               id uuid NOT NULL DEFAULT gen_random_uuid(),
                               address_line_1 text,
                               address_line_2 text,
                               locality text,
                               administrative_area text,
                               postal_code text,
                               country_code common.country_code NOT NULL,
                               latitude numeric(9,6) CHECK (latitude IS NULL OR latitude BETWEEN -90 AND 90),
                               longitude numeric(9,6) CHECK (longitude IS NULL OR longitude BETWEEN -180 AND 180),
                               formatted_address text,
                               validation_status text NOT NULL DEFAULT 'UNVERIFIED'
                                   CHECK (validation_status IN ('UNVERIFIED', 'VALID', 'INVALID', 'PARTIAL')),
                               created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                               updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                               created_by uuid,
                               updated_by uuid,
                               deleted_at timestamptz,
                               deleted_by uuid,
                               version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                               PRIMARY KEY (tenant_id, id),
                               FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                               CHECK (num_nonnulls(address_line_1, locality, administrative_area, postal_code, formatted_address) >= 1)
);

CREATE TABLE crm.account_addresses (
                                       tenant_id uuid NOT NULL,
                                       account_id uuid NOT NULL,
                                       address_id uuid NOT NULL,
                                       address_type text NOT NULL
                                           CHECK (address_type IN ('BILLING', 'SHIPPING', 'OFFICE', 'REGISTERED', 'OTHER')),
                                       is_primary boolean NOT NULL DEFAULT false,
                                       valid_from date,
                                       valid_to date,
                                       created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                       created_by uuid,
                                       PRIMARY KEY (tenant_id, account_id, address_id, address_type),
                                       FOREIGN KEY (tenant_id, account_id)
                                           REFERENCES crm.accounts(tenant_id, id) ON DELETE CASCADE,
                                       FOREIGN KEY (tenant_id, address_id)
                                           REFERENCES crm.addresses(tenant_id, id) ON DELETE CASCADE,
                                       CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);

CREATE UNIQUE INDEX uq_account_addresses_primary_type
    ON crm.account_addresses (tenant_id, account_id, address_type)
    WHERE is_primary AND valid_to IS NULL;

CREATE TABLE crm.contact_addresses (
                                       tenant_id uuid NOT NULL,
                                       contact_id uuid NOT NULL,
                                       address_id uuid NOT NULL,
                                       address_type text NOT NULL
                                           CHECK (address_type IN ('HOME', 'OFFICE', 'MAILING', 'OTHER')),
                                       is_primary boolean NOT NULL DEFAULT false,
                                       valid_from date,
                                       valid_to date,
                                       created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                       created_by uuid,
                                       PRIMARY KEY (tenant_id, contact_id, address_id, address_type),
                                       FOREIGN KEY (tenant_id, contact_id)
                                           REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE,
                                       FOREIGN KEY (tenant_id, address_id)
                                           REFERENCES crm.addresses(tenant_id, id) ON DELETE CASCADE,
                                       CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);

CREATE UNIQUE INDEX uq_contact_addresses_primary_type
    ON crm.contact_addresses (tenant_id, contact_id, address_type)
    WHERE is_primary AND valid_to IS NULL;

-- --------------------------------------------------------------------------
-- Leads and conversion
-- --------------------------------------------------------------------------

CREATE TABLE crm.leads (
                           tenant_id uuid NOT NULL,
                           id uuid NOT NULL DEFAULT gen_random_uuid(),
                           lead_number text NOT NULL,
                           status_id uuid NOT NULL,
                           source_id uuid,
                           owner_user_id uuid,
                           owner_team_id uuid,
                           rating text CHECK (rating IS NULL OR rating IN ('HOT', 'WARM', 'COLD')),
                           account_name text,
                           company_name text,
                           honorific text,
                           given_name text,
                           family_name text,
                           display_name common.nonempty_text NOT NULL,
                           email citext,
                           phone_e164 common.phone_e164,
                           job_title text,
                           website text,
                           country_code common.country_code,
                           preferred_language_code common.language_code,
                           estimated_value common.nonnegative_amount,
                           currency_code common.currency_code,
                           qualification_notes text,
                           disqualification_reason text,
                           converted_at timestamptz,
                           converted_by uuid,
                           converted_account_id uuid,
                           converted_contact_id uuid,
                           converted_opportunity_id uuid,
                           search_vector tsvector GENERATED ALWAYS AS (
                               to_tsvector(
                                       'simple'::regconfig,
                                       coalesce(lead_number, '') || ' ' ||
                                       coalesce(display_name::text, '') || ' ' ||
                                       coalesce(company_name, '') || ' ' ||
                                       coalesce(account_name, '') || ' ' ||
                                       coalesce(email::text, '') || ' ' ||
                                       coalesce(phone_e164::text, '')
                               )
                               ) STORED,
                           created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                           updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                           created_by uuid,
                           updated_by uuid,
                           deleted_at timestamptz,
                           deleted_by uuid,
                           version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                           PRIMARY KEY (tenant_id, id),
                           FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                           FOREIGN KEY (tenant_id, status_id)
                               REFERENCES crm.lead_statuses(tenant_id, id) ON DELETE RESTRICT,
                           FOREIGN KEY (tenant_id, source_id)
                               REFERENCES crm.lead_sources(tenant_id, id) ON DELETE SET NULL (source_id),
                           FOREIGN KEY (tenant_id, owner_user_id)
                               REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                           FOREIGN KEY (tenant_id, owner_team_id)
                               REFERENCES platform.teams(tenant_id, id) ON DELETE SET NULL (owner_team_id),
                           FOREIGN KEY (tenant_id, converted_account_id)
                               REFERENCES crm.accounts(tenant_id, id) ON DELETE SET NULL (converted_account_id),
                           FOREIGN KEY (tenant_id, converted_contact_id)
                               REFERENCES crm.contacts(tenant_id, id) ON DELETE SET NULL (converted_contact_id),
                           CHECK (estimated_value IS NULL OR currency_code IS NOT NULL),
                           CHECK ((converted_at IS NULL AND converted_account_id IS NULL
                               AND converted_contact_id IS NULL AND converted_opportunity_id IS NULL)
                               OR converted_at IS NOT NULL)
);

CREATE UNIQUE INDEX uq_leads_active_number
    ON crm.leads (tenant_id, lead_number)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_leads_owner_status
    ON crm.leads (tenant_id, owner_user_id, status_id, created_at DESC)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_leads_source
    ON crm.leads (tenant_id, source_id, created_at DESC)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_leads_email
    ON crm.leads (tenant_id, email)
    WHERE deleted_at IS NULL AND email IS NOT NULL;
CREATE INDEX idx_leads_phone
    ON crm.leads (tenant_id, phone_e164)
    WHERE deleted_at IS NULL AND phone_e164 IS NOT NULL;
CREATE INDEX idx_leads_search
    ON crm.leads USING gin (search_vector)
    WHERE deleted_at IS NULL;

CREATE TABLE crm.lead_status_history (
                                         tenant_id uuid NOT NULL,
                                         id uuid NOT NULL DEFAULT gen_random_uuid(),
                                         lead_id uuid NOT NULL,
                                         previous_status_id uuid,
                                         new_status_id uuid NOT NULL,
                                         reason text,
                                         changed_by uuid,
                                         changed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                         PRIMARY KEY (tenant_id, id),
                                         FOREIGN KEY (tenant_id, lead_id)
                                             REFERENCES crm.leads(tenant_id, id) ON DELETE CASCADE,
                                         FOREIGN KEY (tenant_id, previous_status_id)
                                             REFERENCES crm.lead_statuses(tenant_id, id) ON DELETE SET NULL (previous_status_id),
                                         FOREIGN KEY (tenant_id, new_status_id)
                                             REFERENCES crm.lead_statuses(tenant_id, id) ON DELETE RESTRICT,
                                         FOREIGN KEY (tenant_id, changed_by)
                                             REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (changed_by),
                                         CHECK (previous_status_id IS NULL OR previous_status_id <> new_status_id)
);

CREATE INDEX idx_lead_status_history_timeline
    ON crm.lead_status_history (tenant_id, lead_id, changed_at DESC);

-- --------------------------------------------------------------------------
-- Pipelines and opportunities
-- --------------------------------------------------------------------------

CREATE TABLE crm.pipelines (
                               tenant_id uuid NOT NULL,
                               id uuid NOT NULL DEFAULT gen_random_uuid(),
                               pipeline_code text NOT NULL,
                               name common.nonempty_text NOT NULL,
                               pipeline_type text NOT NULL DEFAULT 'SALES'
                                   CHECK (pipeline_type IN ('SALES', 'RENEWAL', 'PARTNERSHIP', 'CUSTOM')),
                               is_default boolean NOT NULL DEFAULT false,
                               is_active boolean NOT NULL DEFAULT true,
                               created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                               updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                               created_by uuid,
                               updated_by uuid,
                               version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                               PRIMARY KEY (tenant_id, id),
                               FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                               UNIQUE (tenant_id, pipeline_code)
);

CREATE UNIQUE INDEX uq_pipelines_one_default_type
    ON crm.pipelines (tenant_id, pipeline_type)
    WHERE is_default AND is_active;

CREATE TABLE crm.pipeline_stages (
                                     tenant_id uuid NOT NULL,
                                     id uuid NOT NULL DEFAULT gen_random_uuid(),
                                     pipeline_id uuid NOT NULL,
                                     stage_code text NOT NULL,
                                     name common.nonempty_text NOT NULL,
                                     display_order integer NOT NULL CHECK (display_order >= 0),
                                     default_probability common.percentage NOT NULL DEFAULT 0,
                                     stage_category text NOT NULL DEFAULT 'OPEN'
                                         CHECK (stage_category IN ('OPEN', 'WON', 'LOST')),
                                     forecast_category text NOT NULL DEFAULT 'PIPELINE'
                                         CHECK (forecast_category IN ('OMITTED', 'PIPELINE', 'BEST_CASE', 'COMMIT', 'CLOSED')),
                                     is_active boolean NOT NULL DEFAULT true,
                                     created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     created_by uuid,
                                     updated_by uuid,
                                     version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                     PRIMARY KEY (tenant_id, id),
                                     UNIQUE (tenant_id, pipeline_id, id),
                                     UNIQUE (tenant_id, pipeline_id, stage_code),
                                     UNIQUE (tenant_id, pipeline_id, display_order),
                                     FOREIGN KEY (tenant_id, pipeline_id)
                                         REFERENCES crm.pipelines(tenant_id, id) ON DELETE CASCADE
);

CREATE TABLE crm.opportunities (
                                   tenant_id uuid NOT NULL,
                                   id uuid NOT NULL DEFAULT gen_random_uuid(),
                                   opportunity_number text NOT NULL,
                                   name common.nonempty_text NOT NULL,
                                   account_id uuid NOT NULL,
                                   pipeline_id uuid NOT NULL,
                                   current_stage_id uuid NOT NULL,
                                   owner_user_id uuid,
                                   owner_team_id uuid,
                                   source_id uuid,
                                   primary_contact_id uuid,
                                   opportunity_type text NOT NULL DEFAULT 'NEW_BUSINESS'
                                       CHECK (opportunity_type IN ('NEW_BUSINESS', 'UPSELL', 'CROSS_SELL', 'RENEWAL', 'PARTNERSHIP', 'OTHER')),
                                   status text NOT NULL DEFAULT 'OPEN'
                                       CHECK (status IN ('OPEN', 'WON', 'LOST', 'CANCELLED')),
                                   amount common.nonnegative_amount NOT NULL DEFAULT 0,
                                   currency_code common.currency_code NOT NULL,
                                   probability common.percentage NOT NULL DEFAULT 0,
                                   expected_close_date date,
                                   actual_close_date date,
                                   next_step text,
                                   description text,
                                   lost_reason_id uuid,
                                   lost_reason_notes text,
                                   campaign_id uuid,
                                   search_vector tsvector GENERATED ALWAYS AS (
                                       to_tsvector(
                                               'simple'::regconfig,
                                               coalesce(opportunity_number, '') || ' ' ||
                                               coalesce(name::text, '') || ' ' ||
                                               coalesce(description, '') || ' ' ||
                                               coalesce(next_step, '')
                                       )
                                       ) STORED,
                                   created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                   updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                   created_by uuid,
                                   updated_by uuid,
                                   deleted_at timestamptz,
                                   deleted_by uuid,
                                   version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                   PRIMARY KEY (tenant_id, id),
                                   FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                   FOREIGN KEY (tenant_id, account_id)
                                       REFERENCES crm.accounts(tenant_id, id) ON DELETE RESTRICT,
                                   FOREIGN KEY (tenant_id, pipeline_id)
                                       REFERENCES crm.pipelines(tenant_id, id) ON DELETE RESTRICT,
                                   FOREIGN KEY (tenant_id, pipeline_id, current_stage_id)
                                       REFERENCES crm.pipeline_stages(tenant_id, pipeline_id, id) ON DELETE RESTRICT,
                                   FOREIGN KEY (tenant_id, owner_user_id)
                                       REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                                   FOREIGN KEY (tenant_id, owner_team_id)
                                       REFERENCES platform.teams(tenant_id, id) ON DELETE SET NULL (owner_team_id),
                                   FOREIGN KEY (tenant_id, source_id)
                                       REFERENCES crm.lead_sources(tenant_id, id) ON DELETE SET NULL (source_id),
                                   FOREIGN KEY (tenant_id, primary_contact_id)
                                       REFERENCES crm.contacts(tenant_id, id) ON DELETE SET NULL (primary_contact_id),
                                   FOREIGN KEY (tenant_id, lost_reason_id)
                                       REFERENCES crm.opportunity_lost_reasons(tenant_id, id) ON DELETE SET NULL (lost_reason_id),
                                   CHECK ((status = 'LOST' AND lost_reason_id IS NOT NULL) OR status <> 'LOST'),
                                   CHECK (actual_close_date IS NULL OR status IN ('WON', 'LOST', 'CANCELLED'))
);

CREATE UNIQUE INDEX uq_opportunities_active_number
    ON crm.opportunities (tenant_id, opportunity_number)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_opportunities_pipeline_stage_owner
    ON crm.opportunities (tenant_id, pipeline_id, current_stage_id, owner_user_id)
    WHERE deleted_at IS NULL AND status = 'OPEN';
CREATE INDEX idx_opportunities_expected_close
    ON crm.opportunities (tenant_id, expected_close_date, owner_user_id)
    WHERE deleted_at IS NULL AND status = 'OPEN';
CREATE INDEX idx_opportunities_account
    ON crm.opportunities (tenant_id, account_id, status)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_opportunities_search
    ON crm.opportunities USING gin (search_vector)
    WHERE deleted_at IS NULL;

CREATE TABLE crm.opportunity_contacts (
                                          tenant_id uuid NOT NULL,
                                          opportunity_id uuid NOT NULL,
                                          contact_id uuid NOT NULL,
                                          contact_role text NOT NULL DEFAULT 'OTHER',
                                          is_primary boolean NOT NULL DEFAULT false,
                                          influence_level text
                                              CHECK (influence_level IS NULL OR influence_level IN ('LOW', 'MEDIUM', 'HIGH')),
                                          created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                          created_by uuid,
                                          PRIMARY KEY (tenant_id, opportunity_id, contact_id),
                                          FOREIGN KEY (tenant_id, opportunity_id)
                                              REFERENCES crm.opportunities(tenant_id, id) ON DELETE CASCADE,
                                          FOREIGN KEY (tenant_id, contact_id)
                                              REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE
);

CREATE UNIQUE INDEX uq_opportunity_contacts_one_primary
    ON crm.opportunity_contacts (tenant_id, opportunity_id)
    WHERE is_primary;

CREATE TABLE crm.opportunity_stage_history (
                                               tenant_id uuid NOT NULL,
                                               id uuid NOT NULL DEFAULT gen_random_uuid(),
                                               opportunity_id uuid NOT NULL,
                                               pipeline_id uuid NOT NULL,
                                               from_stage_id uuid,
                                               to_stage_id uuid NOT NULL,
                                               changed_by uuid,
                                               changed_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                               reason text,
                                               PRIMARY KEY (tenant_id, id),
                                               FOREIGN KEY (tenant_id, opportunity_id)
                                                   REFERENCES crm.opportunities(tenant_id, id) ON DELETE CASCADE,
                                               FOREIGN KEY (tenant_id, pipeline_id, from_stage_id)
                                                   REFERENCES crm.pipeline_stages(tenant_id, pipeline_id, id) ON DELETE SET NULL (from_stage_id),
                                               FOREIGN KEY (tenant_id, pipeline_id, to_stage_id)
                                                   REFERENCES crm.pipeline_stages(tenant_id, pipeline_id, id) ON DELETE RESTRICT,
                                               FOREIGN KEY (tenant_id, changed_by)
                                                   REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (changed_by),
                                               CHECK (from_stage_id IS NULL OR from_stage_id <> to_stage_id)
);

CREATE INDEX idx_opportunity_stage_history_timeline
    ON crm.opportunity_stage_history (tenant_id, opportunity_id, changed_at DESC);
CREATE INDEX idx_opportunity_stage_history_stage
    ON crm.opportunity_stage_history (tenant_id, to_stage_id, changed_at DESC);

ALTER TABLE crm.leads
    ADD CONSTRAINT fk_leads_converted_opportunity
        FOREIGN KEY (tenant_id, converted_opportunity_id)
            REFERENCES crm.opportunities(tenant_id, id) ON DELETE SET NULL (converted_opportunity_id);

-- --------------------------------------------------------------------------
-- Activities, notes, tags, and custom fields
-- --------------------------------------------------------------------------

CREATE TABLE crm.activities (
                                tenant_id uuid NOT NULL,
                                id uuid NOT NULL DEFAULT gen_random_uuid(),
                                activity_type text NOT NULL
                                    CHECK (activity_type IN ('CALL', 'EMAIL', 'MEETING', 'TASK', 'MESSAGE', 'DEMO', 'FOLLOW_UP', 'OTHER')),
                                subject common.nonempty_text NOT NULL,
                                description text,
                                direction text CHECK (direction IS NULL OR direction IN ('INBOUND', 'OUTBOUND', 'INTERNAL')),
                                status text NOT NULL DEFAULT 'PLANNED'
                                    CHECK (status IN ('PLANNED', 'IN_PROGRESS', 'COMPLETED', 'CANCELLED', 'DEFERRED')),
                                priority text NOT NULL DEFAULT 'NORMAL'
                                    CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'URGENT')),
                                owner_user_id uuid,
                                assigned_team_id uuid,
                                scheduled_start_at timestamptz,
                                scheduled_end_at timestamptz,
                                completed_at timestamptz,
                                duration_seconds integer CHECK (duration_seconds IS NULL OR duration_seconds >= 0),
                                outcome_code text,
                                external_reference text,
                                recurrence_rule text,
                                metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                created_by uuid,
                                updated_by uuid,
                                deleted_at timestamptz,
                                deleted_by uuid,
                                version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                PRIMARY KEY (tenant_id, id),
                                FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                FOREIGN KEY (tenant_id, owner_user_id)
                                    REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                                FOREIGN KEY (tenant_id, assigned_team_id)
                                    REFERENCES platform.teams(tenant_id, id) ON DELETE SET NULL (assigned_team_id),
                                CHECK (scheduled_end_at IS NULL OR scheduled_start_at IS NULL OR scheduled_end_at >= scheduled_start_at),
                                CHECK (completed_at IS NULL OR status = 'COMPLETED')
);

CREATE INDEX idx_activities_owner_schedule
    ON crm.activities (tenant_id, owner_user_id, scheduled_start_at)
    WHERE deleted_at IS NULL AND status IN ('PLANNED', 'IN_PROGRESS', 'DEFERRED');
CREATE INDEX idx_activities_team_schedule
    ON crm.activities (tenant_id, assigned_team_id, scheduled_start_at)
    WHERE deleted_at IS NULL AND assigned_team_id IS NOT NULL;
CREATE INDEX idx_activities_created
    ON crm.activities (tenant_id, created_at DESC)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_activities_type_created
    ON crm.activities (tenant_id, activity_type, created_at DESC)
    WHERE deleted_at IS NULL;

CREATE TABLE crm.activity_participants (
                                           tenant_id uuid NOT NULL,
                                           activity_id uuid NOT NULL,
                                           id uuid NOT NULL DEFAULT gen_random_uuid(),
                                           user_id uuid,
                                           contact_id uuid,
                                           external_email citext,
                                           participant_role text NOT NULL DEFAULT 'ATTENDEE'
                                               CHECK (participant_role IN ('ORGANIZER', 'ATTENDEE', 'REQUIRED', 'OPTIONAL', 'CC', 'BCC')),
                                           participation_status text
                                               CHECK (participation_status IS NULL OR participation_status IN
                                                                                      ('NEEDS_ACTION', 'ACCEPTED', 'DECLINED', 'TENTATIVE')),
                                           created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                           PRIMARY KEY (tenant_id, id),
                                           FOREIGN KEY (tenant_id, activity_id)
                                               REFERENCES crm.activities(tenant_id, id) ON DELETE CASCADE,
                                           FOREIGN KEY (tenant_id, user_id)
                                               REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE CASCADE,
                                           FOREIGN KEY (tenant_id, contact_id)
                                               REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE,
                                           CHECK (num_nonnulls(user_id, contact_id, external_email) = 1)
);

CREATE INDEX idx_activity_participants_activity
    ON crm.activity_participants (tenant_id, activity_id);
CREATE INDEX idx_activity_participants_contact
    ON crm.activity_participants (tenant_id, contact_id)
    WHERE contact_id IS NOT NULL;

CREATE TABLE crm.activity_links (
                                    tenant_id uuid NOT NULL,
                                    id uuid NOT NULL DEFAULT gen_random_uuid(),
                                    activity_id uuid NOT NULL,
                                    account_id uuid,
                                    contact_id uuid,
                                    lead_id uuid,
                                    opportunity_id uuid,
                                    ticket_id uuid,
                                    relation_role text,
                                    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                    created_by uuid,
                                    PRIMARY KEY (tenant_id, id),
                                    FOREIGN KEY (tenant_id, activity_id)
                                        REFERENCES crm.activities(tenant_id, id) ON DELETE CASCADE,
                                    FOREIGN KEY (tenant_id, account_id)
                                        REFERENCES crm.accounts(tenant_id, id) ON DELETE CASCADE,
                                    FOREIGN KEY (tenant_id, contact_id)
                                        REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE,
                                    FOREIGN KEY (tenant_id, lead_id)
                                        REFERENCES crm.leads(tenant_id, id) ON DELETE CASCADE,
                                    FOREIGN KEY (tenant_id, opportunity_id)
                                        REFERENCES crm.opportunities(tenant_id, id) ON DELETE CASCADE,
                                    CHECK (num_nonnulls(account_id, contact_id, lead_id, opportunity_id, ticket_id) = 1)
);

CREATE INDEX idx_activity_links_activity
    ON crm.activity_links (tenant_id, activity_id);
CREATE INDEX idx_activity_links_account
    ON crm.activity_links (tenant_id, account_id, activity_id) WHERE account_id IS NOT NULL;
CREATE INDEX idx_activity_links_contact
    ON crm.activity_links (tenant_id, contact_id, activity_id) WHERE contact_id IS NOT NULL;
CREATE INDEX idx_activity_links_lead
    ON crm.activity_links (tenant_id, lead_id, activity_id) WHERE lead_id IS NOT NULL;
CREATE INDEX idx_activity_links_opportunity
    ON crm.activity_links (tenant_id, opportunity_id, activity_id) WHERE opportunity_id IS NOT NULL;
CREATE INDEX idx_activity_links_ticket
    ON crm.activity_links (tenant_id, ticket_id, activity_id) WHERE ticket_id IS NOT NULL;

CREATE TABLE crm.notes (
                           tenant_id uuid NOT NULL,
                           id uuid NOT NULL DEFAULT gen_random_uuid(),
                           title text,
                           body common.nonempty_text NOT NULL,
                           visibility text NOT NULL DEFAULT 'TENANT'
                               CHECK (visibility IN ('PRIVATE', 'TEAM', 'TENANT')),
                           owner_user_id uuid,
                           account_id uuid,
                           contact_id uuid,
                           lead_id uuid,
                           opportunity_id uuid,
                           activity_id uuid,
                           ticket_id uuid,
                           created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                           updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                           created_by uuid,
                           updated_by uuid,
                           deleted_at timestamptz,
                           deleted_by uuid,
                           version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                           PRIMARY KEY (tenant_id, id),
                           FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                           FOREIGN KEY (tenant_id, owner_user_id)
                               REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                           FOREIGN KEY (tenant_id, account_id)
                               REFERENCES crm.accounts(tenant_id, id) ON DELETE CASCADE,
                           FOREIGN KEY (tenant_id, contact_id)
                               REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE,
                           FOREIGN KEY (tenant_id, lead_id)
                               REFERENCES crm.leads(tenant_id, id) ON DELETE CASCADE,
                           FOREIGN KEY (tenant_id, opportunity_id)
                               REFERENCES crm.opportunities(tenant_id, id) ON DELETE CASCADE,
                           FOREIGN KEY (tenant_id, activity_id)
                               REFERENCES crm.activities(tenant_id, id) ON DELETE CASCADE,
                           CHECK (num_nonnulls(account_id, contact_id, lead_id, opportunity_id, activity_id, ticket_id) = 1)
);

CREATE INDEX idx_notes_account
    ON crm.notes (tenant_id, account_id, created_at DESC)
    WHERE deleted_at IS NULL AND account_id IS NOT NULL;
CREATE INDEX idx_notes_contact
    ON crm.notes (tenant_id, contact_id, created_at DESC)
    WHERE deleted_at IS NULL AND contact_id IS NOT NULL;
CREATE INDEX idx_notes_lead
    ON crm.notes (tenant_id, lead_id, created_at DESC)
    WHERE deleted_at IS NULL AND lead_id IS NOT NULL;
CREATE INDEX idx_notes_opportunity
    ON crm.notes (tenant_id, opportunity_id, created_at DESC)
    WHERE deleted_at IS NULL AND opportunity_id IS NOT NULL;

CREATE TABLE crm.tags (
                          tenant_id uuid NOT NULL,
                          id uuid NOT NULL DEFAULT gen_random_uuid(),
                          tag_key text NOT NULL,
                          name common.nonempty_text NOT NULL,
                          description text,
                          color_hex varchar(7) CHECK (color_hex IS NULL OR color_hex ~ '^#[0-9A-Fa-f]{6}$'),
  is_active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  created_by uuid,
  updated_by uuid,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  PRIMARY KEY (tenant_id, id),
  FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
  UNIQUE (tenant_id, tag_key)
);

CREATE TABLE crm.entity_tags (
                                 tenant_id uuid NOT NULL,
                                 tag_id uuid NOT NULL,
                                 id uuid NOT NULL DEFAULT gen_random_uuid(),
                                 account_id uuid,
                                 contact_id uuid,
                                 lead_id uuid,
                                 opportunity_id uuid,
                                 activity_id uuid,
                                 ticket_id uuid,
                                 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                 created_by uuid,
                                 PRIMARY KEY (tenant_id, id),
                                 FOREIGN KEY (tenant_id, tag_id)
                                     REFERENCES crm.tags(tenant_id, id) ON DELETE CASCADE,
                                 FOREIGN KEY (tenant_id, account_id)
                                     REFERENCES crm.accounts(tenant_id, id) ON DELETE CASCADE,
                                 FOREIGN KEY (tenant_id, contact_id)
                                     REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE,
                                 FOREIGN KEY (tenant_id, lead_id)
                                     REFERENCES crm.leads(tenant_id, id) ON DELETE CASCADE,
                                 FOREIGN KEY (tenant_id, opportunity_id)
                                     REFERENCES crm.opportunities(tenant_id, id) ON DELETE CASCADE,
                                 FOREIGN KEY (tenant_id, activity_id)
                                     REFERENCES crm.activities(tenant_id, id) ON DELETE CASCADE,
                                 CHECK (num_nonnulls(account_id, contact_id, lead_id, opportunity_id, activity_id, ticket_id) = 1)
);

CREATE INDEX idx_entity_tags_tag
    ON crm.entity_tags (tenant_id, tag_id);
CREATE INDEX idx_entity_tags_account
    ON crm.entity_tags (tenant_id, account_id, tag_id) WHERE account_id IS NOT NULL;
CREATE INDEX idx_entity_tags_contact
    ON crm.entity_tags (tenant_id, contact_id, tag_id) WHERE contact_id IS NOT NULL;
CREATE INDEX idx_entity_tags_lead
    ON crm.entity_tags (tenant_id, lead_id, tag_id) WHERE lead_id IS NOT NULL;
CREATE INDEX idx_entity_tags_opportunity
    ON crm.entity_tags (tenant_id, opportunity_id, tag_id) WHERE opportunity_id IS NOT NULL;

CREATE TABLE crm.custom_field_definitions (
                                              tenant_id uuid NOT NULL,
                                              id uuid NOT NULL DEFAULT gen_random_uuid(),
                                              entity_type text NOT NULL
                                                  CHECK (entity_type IN ('ACCOUNT', 'CONTACT', 'LEAD', 'OPPORTUNITY', 'ACTIVITY', 'TICKET', 'PRODUCT')),
                                              field_key text NOT NULL,
                                              display_name common.nonempty_text NOT NULL,
                                              data_type text NOT NULL
                                                  CHECK (data_type IN ('TEXT', 'LONG_TEXT', 'INTEGER', 'DECIMAL', 'BOOLEAN', 'DATE', 'DATETIME', 'EMAIL', 'PHONE', 'URL', 'SELECT', 'MULTI_SELECT', 'JSON')),
                                              description text,
                                              validation_rules jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(validation_rules) = 'object'),
                                              option_values jsonb NOT NULL DEFAULT '[]'::jsonb
    CHECK (jsonb_typeof(option_values) = 'array'),
                                              is_required boolean NOT NULL DEFAULT false,
                                              is_searchable boolean NOT NULL DEFAULT false,
                                              is_sensitive boolean NOT NULL DEFAULT false,
                                              is_active boolean NOT NULL DEFAULT true,
                                              display_order integer NOT NULL DEFAULT 0,
                                              created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                              updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                              created_by uuid,
                                              updated_by uuid,
                                              version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                              PRIMARY KEY (tenant_id, id),
                                              FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                              UNIQUE (tenant_id, entity_type, field_key)
);

CREATE TABLE crm.custom_field_values (
                                         tenant_id uuid NOT NULL,
                                         id uuid NOT NULL DEFAULT gen_random_uuid(),
                                         definition_id uuid NOT NULL,
                                         entity_type text NOT NULL
                                             CHECK (entity_type IN ('ACCOUNT', 'CONTACT', 'LEAD', 'OPPORTUNITY', 'ACTIVITY', 'TICKET', 'PRODUCT', 'QUOTE', 'ORDER', 'CONTRACT')),
                                         entity_id uuid NOT NULL,
                                         value_jsonb jsonb NOT NULL,
                                         search_text text,
                                         created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                         updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                         created_by uuid,
                                         updated_by uuid,
                                         version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                         PRIMARY KEY (tenant_id, id),
                                         FOREIGN KEY (tenant_id, definition_id)
                                             REFERENCES crm.custom_field_definitions(tenant_id, id) ON DELETE CASCADE,
                                         UNIQUE (tenant_id, definition_id, entity_id)
);

CREATE INDEX idx_custom_field_values_entity
    ON crm.custom_field_values (tenant_id, entity_type, entity_id);
CREATE INDEX idx_custom_field_values_search
    ON crm.custom_field_values USING gin (to_tsvector('simple'::regconfig, coalesce(search_text, '')))
    WHERE search_text IS NOT NULL;

-- --------------------------------------------------------------------------
-- Catalog: products and pricing
-- --------------------------------------------------------------------------

CREATE TABLE catalog.product_categories (
                                            tenant_id uuid NOT NULL,
                                            id uuid NOT NULL DEFAULT gen_random_uuid(),
                                            category_code text NOT NULL,
                                            name common.nonempty_text NOT NULL,
                                            parent_category_id uuid,
                                            description text,
                                            is_active boolean NOT NULL DEFAULT true,
                                            created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            created_by uuid,
                                            updated_by uuid,
                                            version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                            PRIMARY KEY (tenant_id, id),
                                            FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                            FOREIGN KEY (tenant_id, parent_category_id)
                                                REFERENCES catalog.product_categories(tenant_id, id)
                                                ON DELETE SET NULL (parent_category_id),
                                            UNIQUE (tenant_id, category_code)
);

CREATE TABLE catalog.products (
                                  tenant_id uuid NOT NULL,
                                  id uuid NOT NULL DEFAULT gen_random_uuid(),
                                  sku text NOT NULL,
                                  name common.nonempty_text NOT NULL,
                                  description text,
                                  category_id uuid,
                                  product_type text NOT NULL DEFAULT 'PRODUCT'
                                      CHECK (product_type IN ('PRODUCT', 'SERVICE', 'SUBSCRIPTION', 'BUNDLE')),
                                  unit_of_measure text NOT NULL DEFAULT 'EA',
                                  tax_category text,
                                  standard_cost common.nonnegative_amount,
                                  cost_currency_code common.currency_code,
                                  is_active boolean NOT NULL DEFAULT true,
                                  metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                  search_vector tsvector GENERATED ALWAYS AS (
                                      to_tsvector(
                                              'simple'::regconfig,
                                              coalesce(sku, '') || ' ' ||
                                              coalesce(name::text, '') || ' ' ||
                                              coalesce(description, '')
                                      )
                                      ) STORED,
                                  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  created_by uuid,
                                  updated_by uuid,
                                  deleted_at timestamptz,
                                  deleted_by uuid,
                                  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                  PRIMARY KEY (tenant_id, id),
                                  FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                  FOREIGN KEY (tenant_id, category_id)
                                      REFERENCES catalog.product_categories(tenant_id, id)
                                      ON DELETE SET NULL (category_id),
                                  CHECK (standard_cost IS NULL OR cost_currency_code IS NOT NULL)
);

CREATE UNIQUE INDEX uq_products_active_sku
    ON catalog.products (tenant_id, sku)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_products_category
    ON catalog.products (tenant_id, category_id, is_active)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_products_name_trgm
    ON catalog.products USING gin (name gin_trgm_ops)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_products_search
    ON catalog.products USING gin (search_vector)
    WHERE deleted_at IS NULL;

CREATE TABLE catalog.price_books (
                                     tenant_id uuid NOT NULL,
                                     id uuid NOT NULL DEFAULT gen_random_uuid(),
                                     price_book_code text NOT NULL,
                                     name common.nonempty_text NOT NULL,
                                     currency_code common.currency_code NOT NULL,
                                     valid_from date,
                                     valid_to date,
                                     is_default boolean NOT NULL DEFAULT false,
                                     is_active boolean NOT NULL DEFAULT true,
                                     created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     created_by uuid,
                                     updated_by uuid,
                                     version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                     PRIMARY KEY (tenant_id, id),
                                     FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                     UNIQUE (tenant_id, price_book_code),
                                     CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);

CREATE UNIQUE INDEX uq_price_books_one_default_currency
    ON catalog.price_books (tenant_id, currency_code)
    WHERE is_default AND is_active;

CREATE TABLE catalog.price_book_items (
                                          tenant_id uuid NOT NULL,
                                          id uuid NOT NULL DEFAULT gen_random_uuid(),
                                          price_book_id uuid NOT NULL,
                                          product_id uuid NOT NULL,
                                          unit_price common.nonnegative_amount NOT NULL,
                                          minimum_quantity common.positive_quantity NOT NULL DEFAULT 1,
                                          valid_from date,
                                          valid_to date,
                                          created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                          updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                          created_by uuid,
                                          updated_by uuid,
                                          version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                          PRIMARY KEY (tenant_id, id),
                                          FOREIGN KEY (tenant_id, price_book_id)
                                              REFERENCES catalog.price_books(tenant_id, id) ON DELETE CASCADE,
                                          FOREIGN KEY (tenant_id, product_id)
                                              REFERENCES catalog.products(tenant_id, id) ON DELETE RESTRICT,
                                          UNIQUE (tenant_id, price_book_id, product_id, minimum_quantity, valid_from),
                                          CHECK (valid_to IS NULL OR valid_from IS NULL OR valid_to >= valid_from)
);

CREATE INDEX idx_price_book_items_product
    ON catalog.price_book_items (tenant_id, product_id, price_book_id);

-- --------------------------------------------------------------------------
-- Sales: quotes, approvals, orders, contracts
-- --------------------------------------------------------------------------

CREATE TABLE sales.quotes (
                              tenant_id uuid NOT NULL,
                              id uuid NOT NULL DEFAULT gen_random_uuid(),
                              quote_number text NOT NULL,
                              revision_number integer NOT NULL DEFAULT 1 CHECK (revision_number > 0),
                              previous_quote_id uuid,
                              account_id uuid NOT NULL,
                              contact_id uuid,
                              opportunity_id uuid,
                              price_book_id uuid,
                              owner_user_id uuid,
                              status text NOT NULL DEFAULT 'DRAFT'
                                  CHECK (status IN ('DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'SENT', 'ACCEPTED', 'REJECTED', 'EXPIRED', 'CANCELLED')),
                              currency_code common.currency_code NOT NULL,
                              exchange_rate_to_tenant_currency numeric(20,10)
                                  CHECK (exchange_rate_to_tenant_currency IS NULL OR exchange_rate_to_tenant_currency > 0),
                              issue_date date NOT NULL DEFAULT current_date,
                              valid_until date,
                              payment_terms text,
                              delivery_terms text,
                              customer_reference text,
                              billing_address_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(billing_address_snapshot) = 'object'),
                              shipping_address_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(shipping_address_snapshot) = 'object'),
                              subtotal common.nonnegative_amount NOT NULL DEFAULT 0,
                              discount_total common.nonnegative_amount NOT NULL DEFAULT 0,
                              tax_total common.nonnegative_amount NOT NULL DEFAULT 0,
                              shipping_total common.nonnegative_amount NOT NULL DEFAULT 0,
                              grand_total common.nonnegative_amount NOT NULL DEFAULT 0,
                              notes text,
                              approved_at timestamptz,
                              approved_by uuid,
                              accepted_at timestamptz,
                              rejected_at timestamptz,
                              created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                              updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                              created_by uuid,
                              updated_by uuid,
                              version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                              PRIMARY KEY (tenant_id, id),
                              FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                              FOREIGN KEY (tenant_id, previous_quote_id)
                                  REFERENCES sales.quotes(tenant_id, id) ON DELETE SET NULL (previous_quote_id),
                              FOREIGN KEY (tenant_id, account_id)
                                  REFERENCES crm.accounts(tenant_id, id) ON DELETE RESTRICT,
                              FOREIGN KEY (tenant_id, contact_id)
                                  REFERENCES crm.contacts(tenant_id, id) ON DELETE SET NULL (contact_id),
                              FOREIGN KEY (tenant_id, opportunity_id)
                                  REFERENCES crm.opportunities(tenant_id, id) ON DELETE SET NULL (opportunity_id),
                              FOREIGN KEY (tenant_id, price_book_id)
                                  REFERENCES catalog.price_books(tenant_id, id) ON DELETE SET NULL (price_book_id),
                              FOREIGN KEY (tenant_id, owner_user_id)
                                  REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                              FOREIGN KEY (tenant_id, approved_by)
                                  REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (approved_by),
                              CHECK (valid_until IS NULL OR valid_until >= issue_date),
                              CHECK (approved_at IS NULL OR status IN ('APPROVED', 'SENT', 'ACCEPTED', 'REJECTED', 'EXPIRED')),
                              CHECK (accepted_at IS NULL OR status = 'ACCEPTED'),
                              CHECK (rejected_at IS NULL OR status = 'REJECTED')
);

CREATE UNIQUE INDEX uq_quotes_number_revision
    ON sales.quotes (tenant_id, quote_number, revision_number);
CREATE INDEX idx_quotes_account_status
    ON sales.quotes (tenant_id, account_id, status, created_at DESC);
CREATE INDEX idx_quotes_opportunity
    ON sales.quotes (tenant_id, opportunity_id, created_at DESC)
    WHERE opportunity_id IS NOT NULL;
CREATE INDEX idx_quotes_owner_status
    ON sales.quotes (tenant_id, owner_user_id, status, valid_until);

CREATE TABLE sales.quote_items (
                                   tenant_id uuid NOT NULL,
                                   id uuid NOT NULL DEFAULT gen_random_uuid(),
                                   quote_id uuid NOT NULL,
                                   line_number integer NOT NULL CHECK (line_number > 0),
                                   product_id uuid,
                                   sku_snapshot text,
                                   name_snapshot common.nonempty_text NOT NULL,
                                   description_snapshot text,
                                   unit_of_measure_snapshot text,
                                   quantity common.positive_quantity NOT NULL,
                                   unit_price common.nonnegative_amount NOT NULL,
                                   discount_percent common.percentage NOT NULL DEFAULT 0,
                                   discount_amount common.nonnegative_amount NOT NULL DEFAULT 0,
                                   tax_percent common.percentage NOT NULL DEFAULT 0,
                                   tax_amount common.nonnegative_amount NOT NULL DEFAULT 0,
                                   line_subtotal common.nonnegative_amount NOT NULL,
                                   line_total common.nonnegative_amount NOT NULL,
                                   metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                   created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                   updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                   created_by uuid,
                                   updated_by uuid,
                                   version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                   PRIMARY KEY (tenant_id, id),
                                   FOREIGN KEY (tenant_id, quote_id)
                                       REFERENCES sales.quotes(tenant_id, id) ON DELETE CASCADE,
                                   FOREIGN KEY (tenant_id, product_id)
                                       REFERENCES catalog.products(tenant_id, id) ON DELETE SET NULL (product_id),
                                   UNIQUE (tenant_id, quote_id, line_number)
);

CREATE INDEX idx_quote_items_product
    ON sales.quote_items (tenant_id, product_id)
    WHERE product_id IS NOT NULL;

CREATE TABLE sales.quote_approvals (
                                       tenant_id uuid NOT NULL,
                                       id uuid NOT NULL DEFAULT gen_random_uuid(),
                                       quote_id uuid NOT NULL,
                                       approval_level integer NOT NULL DEFAULT 1 CHECK (approval_level > 0),
                                       approver_user_id uuid NOT NULL,
                                       status text NOT NULL DEFAULT 'PENDING'
                                           CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED', 'CANCELLED')),
                                       decision_note text,
                                       requested_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                       decided_at timestamptz,
                                       created_by uuid,
                                       PRIMARY KEY (tenant_id, id),
                                       FOREIGN KEY (tenant_id, quote_id)
                                           REFERENCES sales.quotes(tenant_id, id) ON DELETE CASCADE,
                                       FOREIGN KEY (tenant_id, approver_user_id)
                                           REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE RESTRICT,
                                       UNIQUE (tenant_id, quote_id, approval_level, approver_user_id),
                                       CHECK (decided_at IS NULL OR status IN ('APPROVED', 'REJECTED', 'CANCELLED'))
);

CREATE INDEX idx_quote_approvals_pending
    ON sales.quote_approvals (tenant_id, approver_user_id, requested_at)
    WHERE status = 'PENDING';

CREATE TABLE sales.orders (
                              tenant_id uuid NOT NULL,
                              id uuid NOT NULL DEFAULT gen_random_uuid(),
                              order_number text NOT NULL,
                              account_id uuid NOT NULL,
                              contact_id uuid,
                              opportunity_id uuid,
                              quote_id uuid,
                              owner_user_id uuid,
                              status text NOT NULL DEFAULT 'DRAFT'
                                  CHECK (status IN ('DRAFT', 'CONFIRMED', 'PROCESSING', 'PARTIALLY_FULFILLED', 'FULFILLED', 'CANCELLED')),
                              currency_code common.currency_code NOT NULL,
                              order_date date NOT NULL DEFAULT current_date,
                              requested_delivery_date date,
                              customer_reference text,
                              billing_address_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(billing_address_snapshot) = 'object'),
                              shipping_address_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(shipping_address_snapshot) = 'object'),
                              subtotal common.nonnegative_amount NOT NULL DEFAULT 0,
                              discount_total common.nonnegative_amount NOT NULL DEFAULT 0,
                              tax_total common.nonnegative_amount NOT NULL DEFAULT 0,
                              shipping_total common.nonnegative_amount NOT NULL DEFAULT 0,
                              grand_total common.nonnegative_amount NOT NULL DEFAULT 0,
                              confirmed_at timestamptz,
                              fulfilled_at timestamptz,
                              cancelled_at timestamptz,
                              cancellation_reason text,
                              created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                              updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                              created_by uuid,
                              updated_by uuid,
                              version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                              PRIMARY KEY (tenant_id, id),
                              FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                              FOREIGN KEY (tenant_id, account_id)
                                  REFERENCES crm.accounts(tenant_id, id) ON DELETE RESTRICT,
                              FOREIGN KEY (tenant_id, contact_id)
                                  REFERENCES crm.contacts(tenant_id, id) ON DELETE SET NULL (contact_id),
                              FOREIGN KEY (tenant_id, opportunity_id)
                                  REFERENCES crm.opportunities(tenant_id, id) ON DELETE SET NULL (opportunity_id),
                              FOREIGN KEY (tenant_id, quote_id)
                                  REFERENCES sales.quotes(tenant_id, id) ON DELETE SET NULL (quote_id),
                              FOREIGN KEY (tenant_id, owner_user_id)
                                  REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                              UNIQUE (tenant_id, order_number),
                              CHECK (requested_delivery_date IS NULL OR requested_delivery_date >= order_date),
                              CHECK (confirmed_at IS NULL OR status <> 'DRAFT'),
                              CHECK (fulfilled_at IS NULL OR status = 'FULFILLED'),
                              CHECK (cancelled_at IS NULL OR status = 'CANCELLED')
);

CREATE INDEX idx_orders_account_status
    ON sales.orders (tenant_id, account_id, status, order_date DESC);
CREATE INDEX idx_orders_owner_status
    ON sales.orders (tenant_id, owner_user_id, status, order_date DESC);
CREATE INDEX idx_orders_opportunity
    ON sales.orders (tenant_id, opportunity_id, order_date DESC)
    WHERE opportunity_id IS NOT NULL;

CREATE TABLE sales.order_items (
                                   tenant_id uuid NOT NULL,
                                   id uuid NOT NULL DEFAULT gen_random_uuid(),
                                   order_id uuid NOT NULL,
                                   line_number integer NOT NULL CHECK (line_number > 0),
                                   product_id uuid,
                                   quote_item_id uuid,
                                   sku_snapshot text,
                                   name_snapshot common.nonempty_text NOT NULL,
                                   description_snapshot text,
                                   unit_of_measure_snapshot text,
                                   quantity common.positive_quantity NOT NULL,
                                   fulfilled_quantity numeric(20,6) NOT NULL DEFAULT 0 CHECK (fulfilled_quantity >= 0),
                                   unit_price common.nonnegative_amount NOT NULL,
                                   discount_amount common.nonnegative_amount NOT NULL DEFAULT 0,
                                   tax_amount common.nonnegative_amount NOT NULL DEFAULT 0,
                                   line_total common.nonnegative_amount NOT NULL,
                                   created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                   updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                   created_by uuid,
                                   updated_by uuid,
                                   version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                   PRIMARY KEY (tenant_id, id),
                                   FOREIGN KEY (tenant_id, order_id)
                                       REFERENCES sales.orders(tenant_id, id) ON DELETE CASCADE,
                                   FOREIGN KEY (tenant_id, product_id)
                                       REFERENCES catalog.products(tenant_id, id) ON DELETE SET NULL (product_id),
                                   FOREIGN KEY (tenant_id, quote_item_id)
                                       REFERENCES sales.quote_items(tenant_id, id) ON DELETE SET NULL (quote_item_id),
                                   UNIQUE (tenant_id, order_id, line_number),
                                   CHECK (fulfilled_quantity <= quantity)
);

CREATE TABLE sales.contracts (
                                 tenant_id uuid NOT NULL,
                                 id uuid NOT NULL DEFAULT gen_random_uuid(),
                                 contract_number text NOT NULL,
                                 account_id uuid NOT NULL,
                                 contact_id uuid,
                                 opportunity_id uuid,
                                 quote_id uuid,
                                 order_id uuid,
                                 owner_user_id uuid,
                                 contract_type text NOT NULL DEFAULT 'CUSTOMER'
                                     CHECK (contract_type IN ('CUSTOMER', 'SUBSCRIPTION', 'SERVICE', 'FRAMEWORK', 'NDA', 'OTHER')),
                                 status text NOT NULL DEFAULT 'DRAFT'
                                     CHECK (status IN ('DRAFT', 'IN_REVIEW', 'APPROVED', 'SENT_FOR_SIGNATURE', 'ACTIVE', 'EXPIRED', 'TERMINATED', 'CANCELLED')),
                                 currency_code common.currency_code,
                                 contract_value common.nonnegative_amount,
                                 effective_from date,
                                 effective_to date,
                                 auto_renew boolean NOT NULL DEFAULT false,
                                 renewal_notice_days integer CHECK (renewal_notice_days IS NULL OR renewal_notice_days >= 0),
                                 signed_at timestamptz,
                                 terminated_at timestamptz,
                                 termination_reason text,
                                 document_reference text,
                                 terms_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(terms_snapshot) = 'object'),
                                 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                 updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                 created_by uuid,
                                 updated_by uuid,
                                 version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                 PRIMARY KEY (tenant_id, id),
                                 FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                 FOREIGN KEY (tenant_id, account_id)
                                     REFERENCES crm.accounts(tenant_id, id) ON DELETE RESTRICT,
                                 FOREIGN KEY (tenant_id, contact_id)
                                     REFERENCES crm.contacts(tenant_id, id) ON DELETE SET NULL (contact_id),
                                 FOREIGN KEY (tenant_id, opportunity_id)
                                     REFERENCES crm.opportunities(tenant_id, id) ON DELETE SET NULL (opportunity_id),
                                 FOREIGN KEY (tenant_id, quote_id)
                                     REFERENCES sales.quotes(tenant_id, id) ON DELETE SET NULL (quote_id),
                                 FOREIGN KEY (tenant_id, order_id)
                                     REFERENCES sales.orders(tenant_id, id) ON DELETE SET NULL (order_id),
                                 FOREIGN KEY (tenant_id, owner_user_id)
                                     REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                                 UNIQUE (tenant_id, contract_number),
                                 CHECK (effective_to IS NULL OR effective_from IS NULL OR effective_to >= effective_from),
                                 CHECK (contract_value IS NULL OR currency_code IS NOT NULL),
                                 CHECK (signed_at IS NULL OR status IN ('ACTIVE', 'EXPIRED', 'TERMINATED')),
                                 CHECK (terminated_at IS NULL OR status = 'TERMINATED')
);

CREATE INDEX idx_contracts_account_status
    ON sales.contracts (tenant_id, account_id, status, effective_to);
CREATE INDEX idx_contracts_renewal
    ON sales.contracts (tenant_id, effective_to, owner_user_id)
    WHERE status = 'ACTIVE' AND auto_renew;

-- --------------------------------------------------------------------------
-- Marketing: campaigns and members
-- --------------------------------------------------------------------------

CREATE TABLE marketing.campaigns (
                                     tenant_id uuid NOT NULL,
                                     id uuid NOT NULL DEFAULT gen_random_uuid(),
                                     campaign_code text NOT NULL,
                                     name common.nonempty_text NOT NULL,
                                     campaign_type text NOT NULL
                                         CHECK (campaign_type IN ('EMAIL', 'EVENT', 'WEBINAR', 'ADVERTISING', 'SOCIAL', 'PARTNER', 'DIRECT_MAIL', 'OTHER')),
                                     status text NOT NULL DEFAULT 'PLANNED'
                                         CHECK (status IN ('PLANNED', 'ACTIVE', 'PAUSED', 'COMPLETED', 'CANCELLED')),
                                     owner_user_id uuid,
                                     start_at timestamptz,
                                     end_at timestamptz,
                                     budget common.nonnegative_amount,
                                     actual_cost common.nonnegative_amount,
                                     currency_code common.currency_code,
                                     expected_revenue common.nonnegative_amount,
                                     description text,
                                     utm_source text,
                                     utm_medium text,
                                     utm_campaign text,
                                     created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     created_by uuid,
                                     updated_by uuid,
                                     deleted_at timestamptz,
                                     deleted_by uuid,
                                     version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                     PRIMARY KEY (tenant_id, id),
                                     FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                     FOREIGN KEY (tenant_id, owner_user_id)
                                         REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                                     CHECK (end_at IS NULL OR start_at IS NULL OR end_at >= start_at),
                                     CHECK (num_nonnulls(budget, actual_cost, expected_revenue) = 0 OR currency_code IS NOT NULL)
);

CREATE UNIQUE INDEX uq_campaigns_active_code
    ON marketing.campaigns (tenant_id, campaign_code)
    WHERE deleted_at IS NULL;
CREATE INDEX idx_campaigns_status_dates
    ON marketing.campaigns (tenant_id, status, start_at, end_at)
    WHERE deleted_at IS NULL;

CREATE TABLE marketing.campaign_members (
                                            tenant_id uuid NOT NULL,
                                            id uuid NOT NULL DEFAULT gen_random_uuid(),
                                            campaign_id uuid NOT NULL,
                                            lead_id uuid,
                                            contact_id uuid,
                                            member_status text NOT NULL DEFAULT 'SENT'
                                                CHECK (member_status IN ('PLANNED', 'SENT', 'DELIVERED', 'OPENED', 'CLICKED', 'RESPONDED', 'ATTENDED', 'BOUNCED', 'OPTED_OUT')),
                                            source_detail text,
                                            first_responded_at timestamptz,
                                            last_engaged_at timestamptz,
                                            metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                            created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            created_by uuid,
                                            updated_by uuid,
                                            version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                            PRIMARY KEY (tenant_id, id),
                                            FOREIGN KEY (tenant_id, campaign_id)
                                                REFERENCES marketing.campaigns(tenant_id, id) ON DELETE CASCADE,
                                            FOREIGN KEY (tenant_id, lead_id)
                                                REFERENCES crm.leads(tenant_id, id) ON DELETE CASCADE,
                                            FOREIGN KEY (tenant_id, contact_id)
                                                REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE,
                                            CHECK (num_nonnulls(lead_id, contact_id) = 1)
);

CREATE UNIQUE INDEX uq_campaign_members_lead
    ON marketing.campaign_members (tenant_id, campaign_id, lead_id)
    WHERE lead_id IS NOT NULL;
CREATE UNIQUE INDEX uq_campaign_members_contact
    ON marketing.campaign_members (tenant_id, campaign_id, contact_id)
    WHERE contact_id IS NOT NULL;
CREATE INDEX idx_campaign_members_status
    ON marketing.campaign_members (tenant_id, campaign_id, member_status);

ALTER TABLE crm.opportunities
    ADD CONSTRAINT fk_opportunities_campaign
        FOREIGN KEY (tenant_id, campaign_id)
            REFERENCES marketing.campaigns(tenant_id, id)
            ON DELETE SET NULL (campaign_id);

-- --------------------------------------------------------------------------
-- Customer service: categories, SLAs, tickets, comments, events
-- --------------------------------------------------------------------------

CREATE TABLE service.ticket_categories (
                                           tenant_id uuid NOT NULL,
                                           id uuid NOT NULL DEFAULT gen_random_uuid(),
                                           category_code text NOT NULL,
                                           name common.nonempty_text NOT NULL,
                                           parent_category_id uuid,
                                           default_team_id uuid,
                                           description text,
                                           is_active boolean NOT NULL DEFAULT true,
                                           created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                           updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                           created_by uuid,
                                           updated_by uuid,
                                           version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                           PRIMARY KEY (tenant_id, id),
                                           FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                           FOREIGN KEY (tenant_id, parent_category_id)
                                               REFERENCES service.ticket_categories(tenant_id, id)
                                               ON DELETE SET NULL (parent_category_id),
                                           FOREIGN KEY (tenant_id, default_team_id)
                                               REFERENCES platform.teams(tenant_id, id)
                                               ON DELETE SET NULL (default_team_id),
                                           UNIQUE (tenant_id, category_code)
);

CREATE TABLE service.sla_policies (
                                      tenant_id uuid NOT NULL,
                                      id uuid NOT NULL DEFAULT gen_random_uuid(),
                                      policy_code text NOT NULL,
                                      name common.nonempty_text NOT NULL,
                                      priority text NOT NULL
                                          CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'URGENT')),
                                      first_response_minutes integer NOT NULL CHECK (first_response_minutes > 0),
                                      resolution_minutes integer NOT NULL CHECK (resolution_minutes > 0),
                                      business_hours_calendar_key text,
                                      pause_on_statuses text[] NOT NULL DEFAULT ARRAY['WAITING_CUSTOMER']::text[],
                                      is_default boolean NOT NULL DEFAULT false,
                                      is_active boolean NOT NULL DEFAULT true,
                                      created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                      updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                      created_by uuid,
                                      updated_by uuid,
                                      version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                      PRIMARY KEY (tenant_id, id),
                                      FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                      UNIQUE (tenant_id, policy_code),
                                      CHECK (resolution_minutes >= first_response_minutes)
);

CREATE UNIQUE INDEX uq_sla_policies_default_priority
    ON service.sla_policies (tenant_id, priority)
    WHERE is_default AND is_active;

CREATE TABLE service.tickets (
                                 tenant_id uuid NOT NULL,
                                 id uuid NOT NULL DEFAULT gen_random_uuid(),
                                 ticket_number text NOT NULL,
                                 account_id uuid,
                                 contact_id uuid,
                                 subject common.nonempty_text NOT NULL,
                                 description text,
                                 channel text NOT NULL DEFAULT 'WEB'
                                     CHECK (channel IN ('EMAIL', 'PHONE', 'WEB', 'CHAT', 'SOCIAL', 'API', 'INTERNAL', 'OTHER')),
                                 category_id uuid,
                                 priority text NOT NULL DEFAULT 'NORMAL'
                                     CHECK (priority IN ('LOW', 'NORMAL', 'HIGH', 'URGENT')),
                                 severity text
                                     CHECK (severity IS NULL OR severity IN ('S1', 'S2', 'S3', 'S4')),
                                 status text NOT NULL DEFAULT 'NEW'
                                     CHECK (status IN ('NEW', 'OPEN', 'PENDING', 'WAITING_CUSTOMER', 'RESOLVED', 'CLOSED', 'CANCELLED')),
                                 assigned_user_id uuid,
                                 assigned_team_id uuid,
                                 owner_user_id uuid,
                                 sla_policy_id uuid,
                                 external_reference text,
                                 first_response_due_at timestamptz,
                                 resolution_due_at timestamptz,
                                 first_responded_at timestamptz,
                                 resolved_at timestamptz,
                                 closed_at timestamptz,
                                 satisfaction_score smallint CHECK (satisfaction_score IS NULL OR satisfaction_score BETWEEN 1 AND 5),
                                 satisfaction_comment text,
                                 search_vector tsvector GENERATED ALWAYS AS (
                                     to_tsvector(
                                             'simple'::regconfig,
                                             coalesce(ticket_number, '') || ' ' ||
                                             coalesce(subject::text, '') || ' ' ||
                                             coalesce(description, '') || ' ' ||
                                             coalesce(external_reference, '')
                                     )
                                     ) STORED,
                                 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                 updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                 created_by uuid,
                                 updated_by uuid,
                                 version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                 PRIMARY KEY (tenant_id, id),
                                 FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                 FOREIGN KEY (tenant_id, account_id)
                                     REFERENCES crm.accounts(tenant_id, id) ON DELETE SET NULL (account_id),
                                 FOREIGN KEY (tenant_id, contact_id)
                                     REFERENCES crm.contacts(tenant_id, id) ON DELETE SET NULL (contact_id),
                                 FOREIGN KEY (tenant_id, category_id)
                                     REFERENCES service.ticket_categories(tenant_id, id) ON DELETE SET NULL (category_id),
                                 FOREIGN KEY (tenant_id, assigned_user_id)
                                     REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (assigned_user_id),
                                 FOREIGN KEY (tenant_id, assigned_team_id)
                                     REFERENCES platform.teams(tenant_id, id) ON DELETE SET NULL (assigned_team_id),
                                 FOREIGN KEY (tenant_id, owner_user_id)
                                     REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (owner_user_id),
                                 FOREIGN KEY (tenant_id, sla_policy_id)
                                     REFERENCES service.sla_policies(tenant_id, id) ON DELETE SET NULL (sla_policy_id),
                                 UNIQUE (tenant_id, ticket_number),
                                 CHECK (num_nonnulls(account_id, contact_id) >= 1),
                                 CHECK (resolved_at IS NULL OR status IN ('RESOLVED', 'CLOSED')),
                                 CHECK (closed_at IS NULL OR status = 'CLOSED')
);

CREATE INDEX idx_tickets_assignee_status
    ON service.tickets (tenant_id, assigned_user_id, status, priority, created_at DESC);
CREATE INDEX idx_tickets_team_status
    ON service.tickets (tenant_id, assigned_team_id, status, priority, created_at DESC);
CREATE INDEX idx_tickets_account
    ON service.tickets (tenant_id, account_id, created_at DESC)
    WHERE account_id IS NOT NULL;
CREATE INDEX idx_tickets_contact
    ON service.tickets (tenant_id, contact_id, created_at DESC)
    WHERE contact_id IS NOT NULL;
CREATE INDEX idx_tickets_sla_due
    ON service.tickets (tenant_id, resolution_due_at, priority)
    WHERE status NOT IN ('RESOLVED', 'CLOSED', 'CANCELLED');
CREATE INDEX idx_tickets_search
    ON service.tickets USING gin (search_vector);

CREATE TABLE service.ticket_comments (
                                         tenant_id uuid NOT NULL,
                                         id uuid NOT NULL DEFAULT gen_random_uuid(),
                                         ticket_id uuid NOT NULL,
                                         author_user_id uuid,
                                         author_contact_id uuid,
                                         body common.nonempty_text NOT NULL,
                                         visibility text NOT NULL DEFAULT 'PUBLIC'
                                             CHECK (visibility IN ('PUBLIC', 'INTERNAL')),
                                         channel text,
                                         external_message_id text,
                                         created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                         updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                         created_by uuid,
                                         updated_by uuid,
                                         deleted_at timestamptz,
                                         deleted_by uuid,
                                         version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                         PRIMARY KEY (tenant_id, id),
                                         FOREIGN KEY (tenant_id, ticket_id)
                                             REFERENCES service.tickets(tenant_id, id) ON DELETE CASCADE,
                                         FOREIGN KEY (tenant_id, author_user_id)
                                             REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (author_user_id),
                                         FOREIGN KEY (tenant_id, author_contact_id)
                                             REFERENCES crm.contacts(tenant_id, id) ON DELETE SET NULL (author_contact_id),
                                         CHECK (num_nonnulls(author_user_id, author_contact_id) <= 1)
);

CREATE INDEX idx_ticket_comments_timeline
    ON service.ticket_comments (tenant_id, ticket_id, created_at);

CREATE TABLE service.ticket_events (
                                       tenant_id uuid NOT NULL,
                                       occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                       id uuid NOT NULL DEFAULT gen_random_uuid(),
                                       ticket_id uuid NOT NULL,
                                       event_type text NOT NULL,
                                       field_name text,
                                       old_value jsonb,
                                       new_value jsonb,
                                       actor_user_id uuid,
                                       request_id uuid,
                                       metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                       PRIMARY KEY (tenant_id, occurred_at, id),
                                       FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                       FOREIGN KEY (tenant_id, ticket_id)
                                           REFERENCES service.tickets(tenant_id, id) ON DELETE CASCADE,
                                       FOREIGN KEY (tenant_id, actor_user_id)
                                           REFERENCES platform.tenant_memberships(tenant_id, user_id)
                                           ON DELETE SET NULL (actor_user_id)
) PARTITION BY RANGE (occurred_at);

CREATE INDEX idx_ticket_events_ticket_timeline
    ON service.ticket_events (tenant_id, ticket_id, occurred_at DESC);
CREATE INDEX idx_ticket_events_brin_time
    ON service.ticket_events USING brin (occurred_at);

ALTER TABLE crm.activity_links
    ADD CONSTRAINT fk_activity_links_ticket
        FOREIGN KEY (tenant_id, ticket_id)
            REFERENCES service.tickets(tenant_id, id) ON DELETE CASCADE;

ALTER TABLE crm.notes
    ADD CONSTRAINT fk_notes_ticket
        FOREIGN KEY (tenant_id, ticket_id)
            REFERENCES service.tickets(tenant_id, id) ON DELETE CASCADE;

ALTER TABLE crm.entity_tags
    ADD CONSTRAINT fk_entity_tags_ticket
        FOREIGN KEY (tenant_id, ticket_id)
            REFERENCES service.tickets(tenant_id, id) ON DELETE CASCADE;

-- --------------------------------------------------------------------------
-- Privacy: consent, retention, and data-subject requests
-- --------------------------------------------------------------------------

CREATE TABLE privacy.consents (
                                  tenant_id uuid NOT NULL,
                                  id uuid NOT NULL DEFAULT gen_random_uuid(),
                                  account_id uuid,
                                  contact_id uuid,
                                  lead_id uuid,
                                  channel text NOT NULL
                                      CHECK (channel IN ('EMAIL', 'PHONE', 'SMS', 'WHATSAPP', 'PUSH', 'POSTAL', 'OTHER')),
                                  purpose text NOT NULL,
                                  lawful_basis text NOT NULL
                                      CHECK (lawful_basis IN ('CONSENT', 'CONTRACT', 'LEGAL_OBLIGATION', 'VITAL_INTERESTS', 'PUBLIC_TASK', 'LEGITIMATE_INTERESTS')),
                                  consent_status text NOT NULL
                                      CHECK (consent_status IN ('GRANTED', 'DENIED', 'WITHDRAWN', 'EXPIRED')),
                                  policy_version text,
                                  source text,
                                  proof_reference text,
                                  captured_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  effective_from timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  expires_at timestamptz,
                                  withdrawn_at timestamptz,
                                  recorded_by uuid,
                                  metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                  PRIMARY KEY (tenant_id, id),
                                  FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                  FOREIGN KEY (tenant_id, account_id)
                                      REFERENCES crm.accounts(tenant_id, id) ON DELETE CASCADE,
                                  FOREIGN KEY (tenant_id, contact_id)
                                      REFERENCES crm.contacts(tenant_id, id) ON DELETE CASCADE,
                                  FOREIGN KEY (tenant_id, lead_id)
                                      REFERENCES crm.leads(tenant_id, id) ON DELETE CASCADE,
                                  FOREIGN KEY (tenant_id, recorded_by)
                                      REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (recorded_by),
                                  CHECK (num_nonnulls(account_id, contact_id, lead_id) = 1),
                                  CHECK (expires_at IS NULL OR expires_at > effective_from),
                                  CHECK (withdrawn_at IS NULL OR consent_status = 'WITHDRAWN')
);

CREATE INDEX idx_consents_contact_current
    ON privacy.consents (tenant_id, contact_id, purpose, channel, effective_from DESC)
    WHERE contact_id IS NOT NULL;
CREATE INDEX idx_consents_lead_current
    ON privacy.consents (tenant_id, lead_id, purpose, channel, effective_from DESC)
    WHERE lead_id IS NOT NULL;
CREATE INDEX idx_consents_account_current
    ON privacy.consents (tenant_id, account_id, purpose, channel, effective_from DESC)
    WHERE account_id IS NOT NULL;

CREATE VIEW privacy.current_consents
            WITH (security_barrier = true, security_invoker = true)
AS
SELECT DISTINCT ON (
    tenant_id,
    COALESCE(account_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(contact_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(lead_id, '00000000-0000-0000-0000-000000000000'::uuid),
    channel,
    purpose
    )
    tenant_id,
    id,
    account_id,
    contact_id,
    lead_id,
    channel,
    purpose,
    lawful_basis,
    consent_status,
    policy_version,
    source,
    effective_from,
    expires_at,
    withdrawn_at
FROM privacy.consents
ORDER BY
    tenant_id,
    COALESCE(account_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(contact_id, '00000000-0000-0000-0000-000000000000'::uuid),
    COALESCE(lead_id, '00000000-0000-0000-0000-000000000000'::uuid),
    channel,
    purpose,
    effective_from DESC,
    created_at DESC;

CREATE TABLE privacy.retention_policies (
                                            tenant_id uuid NOT NULL,
                                            id uuid NOT NULL DEFAULT gen_random_uuid(),
                                            entity_type text NOT NULL,
                                            purpose text NOT NULL,
                                            retention_days integer NOT NULL CHECK (retention_days >= 0),
                                            action_on_expiry text NOT NULL
                                                CHECK (action_on_expiry IN ('DELETE', 'ANONYMIZE', 'ARCHIVE', 'REVIEW')),
                                            legal_basis text,
                                            is_active boolean NOT NULL DEFAULT true,
                                            created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                            created_by uuid,
                                            updated_by uuid,
                                            version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                            PRIMARY KEY (tenant_id, id),
                                            FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                            UNIQUE (tenant_id, entity_type, purpose)
);

CREATE TABLE privacy.data_subject_requests (
                                               tenant_id uuid NOT NULL,
                                               id uuid NOT NULL DEFAULT gen_random_uuid(),
                                               request_number text NOT NULL,
                                               request_type text NOT NULL
                                                   CHECK (request_type IN ('ACCESS', 'RECTIFICATION', 'ERASURE', 'RESTRICTION', 'PORTABILITY', 'OBJECTION')),
                                               account_id uuid,
                                               contact_id uuid,
                                               lead_id uuid,
                                               requester_email citext,
                                               status text NOT NULL DEFAULT 'RECEIVED'
                                                   CHECK (status IN ('RECEIVED', 'IDENTITY_VERIFICATION', 'IN_PROGRESS', 'COMPLETED', 'REJECTED', 'CANCELLED')),
                                               received_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                               due_at timestamptz,
                                               completed_at timestamptz,
                                               assigned_user_id uuid,
                                               verification_reference text,
                                               resolution_summary text,
                                               rejection_reason text,
                                               created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                               updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                               created_by uuid,
                                               updated_by uuid,
                                               version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                               PRIMARY KEY (tenant_id, id),
                                               FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                               FOREIGN KEY (tenant_id, account_id)
                                                   REFERENCES crm.accounts(tenant_id, id) ON DELETE SET NULL (account_id),
                                               FOREIGN KEY (tenant_id, contact_id)
                                                   REFERENCES crm.contacts(tenant_id, id) ON DELETE SET NULL (contact_id),
                                               FOREIGN KEY (tenant_id, lead_id)
                                                   REFERENCES crm.leads(tenant_id, id) ON DELETE SET NULL (lead_id),
                                               FOREIGN KEY (tenant_id, assigned_user_id)
                                                   REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (assigned_user_id),
                                               UNIQUE (tenant_id, request_number),
                                               CHECK (num_nonnulls(account_id, contact_id, lead_id, requester_email) >= 1),
                                               CHECK (due_at IS NULL OR due_at >= received_at),
                                               CHECK (completed_at IS NULL OR status = 'COMPLETED')
);

CREATE INDEX idx_data_subject_requests_due
    ON privacy.data_subject_requests (tenant_id, status, due_at)
    WHERE status NOT IN ('COMPLETED', 'REJECTED', 'CANCELLED');

CREATE TABLE privacy.legal_holds (
                                     tenant_id uuid NOT NULL,
                                     id uuid NOT NULL DEFAULT gen_random_uuid(),
                                     hold_code text NOT NULL,
                                     name common.nonempty_text NOT NULL,
                                     entity_type text NOT NULL,
                                     entity_id uuid,
                                     scope_filter jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(scope_filter) = 'object'),
                                     reason common.nonempty_text NOT NULL,
                                     effective_from timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     released_at timestamptz,
                                     released_by uuid,
                                     created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                     created_by uuid,
                                     PRIMARY KEY (tenant_id, id),
                                     FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                     FOREIGN KEY (tenant_id, released_by)
                                         REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (released_by),
                                     UNIQUE (tenant_id, hold_code),
                                     CHECK (released_at IS NULL OR released_at >= effective_from)
);

-- --------------------------------------------------------------------------
-- Integration: external mappings, outbox, webhooks, idempotency, imports
-- --------------------------------------------------------------------------

CREATE TABLE integration.external_id_mappings (
                                                  tenant_id uuid NOT NULL,
                                                  id uuid NOT NULL DEFAULT gen_random_uuid(),
                                                  integration_key text NOT NULL,
                                                  entity_type text NOT NULL,
                                                  internal_entity_id uuid NOT NULL,
                                                  external_entity_id text NOT NULL,
                                                  external_version text,
                                                  last_synced_at timestamptz,
                                                  metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                                  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                                  updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                                  created_by uuid,
                                                  updated_by uuid,
                                                  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                                  PRIMARY KEY (tenant_id, id),
                                                  FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                                  UNIQUE (tenant_id, integration_key, entity_type, external_entity_id),
                                                  UNIQUE (tenant_id, integration_key, entity_type, internal_entity_id)
);

CREATE TABLE integration.outbox_events (
                                           tenant_id uuid NOT NULL,
                                           created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                           id uuid NOT NULL DEFAULT gen_random_uuid(),
                                           aggregate_type text NOT NULL,
                                           aggregate_id uuid NOT NULL,
                                           event_type text NOT NULL,
                                           event_version integer NOT NULL DEFAULT 1 CHECK (event_version > 0),
                                           payload jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
                                           headers jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(headers) = 'object'),
                                           correlation_id uuid,
                                           causation_id uuid,
                                           deduplication_key text,
                                           status text NOT NULL DEFAULT 'PENDING'
                                               CHECK (status IN ('PENDING', 'PROCESSING', 'PUBLISHED', 'FAILED', 'DEAD')),
                                           available_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                           locked_at timestamptz,
                                           locked_by text,
                                           published_at timestamptz,
                                           retry_count integer NOT NULL DEFAULT 0 CHECK (retry_count >= 0),
                                           last_error text,
                                           PRIMARY KEY (tenant_id, created_at, id),
                                           FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                           CHECK (published_at IS NULL OR status = 'PUBLISHED')
) PARTITION BY RANGE (created_at);

CREATE INDEX idx_outbox_pending
    ON integration.outbox_events (tenant_id, status, available_at, created_at)
    WHERE status IN ('PENDING', 'FAILED');
CREATE INDEX idx_outbox_lock_recovery
    ON integration.outbox_events (status, locked_at)
    WHERE status = 'PROCESSING';
CREATE INDEX idx_outbox_aggregate
    ON integration.outbox_events (tenant_id, aggregate_type, aggregate_id, created_at DESC);
CREATE INDEX idx_outbox_brin_time
    ON integration.outbox_events USING brin (created_at);

CREATE TABLE integration.webhook_subscriptions (
                                                   tenant_id uuid NOT NULL,
                                                   id uuid NOT NULL DEFAULT gen_random_uuid(),
                                                   name common.nonempty_text NOT NULL,
                                                   endpoint_url common.nonempty_text NOT NULL,
                                                   event_types text[] NOT NULL CHECK (cardinality(event_types) > 0),
                                                   secret_reference text,
                                                   signature_algorithm text NOT NULL DEFAULT 'HMAC_SHA256'
                                                       CHECK (signature_algorithm IN ('HMAC_SHA256', 'HMAC_SHA512', 'NONE')),
                                                   custom_headers jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(custom_headers) = 'object'),
                                                   timeout_seconds integer NOT NULL DEFAULT 10 CHECK (timeout_seconds BETWEEN 1 AND 120),
                                                   max_retries integer NOT NULL DEFAULT 8 CHECK (max_retries BETWEEN 0 AND 100),
                                                   status text NOT NULL DEFAULT 'ACTIVE'
                                                       CHECK (status IN ('ACTIVE', 'PAUSED', 'DISABLED')),
                                                   last_success_at timestamptz,
                                                   last_failure_at timestamptz,
                                                   created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                                   updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                                   created_by uuid,
                                                   updated_by uuid,
                                                   version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                                   PRIMARY KEY (tenant_id, id),
                                                   FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE
);

CREATE INDEX idx_webhook_subscriptions_active
    ON integration.webhook_subscriptions (tenant_id, status)
    WHERE status = 'ACTIVE';

CREATE TABLE integration.webhook_deliveries (
                                                tenant_id uuid NOT NULL,
                                                created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                                id uuid NOT NULL DEFAULT gen_random_uuid(),
                                                subscription_id uuid NOT NULL,
                                                outbox_event_id uuid,
                                                event_type text NOT NULL,
                                                attempt_number integer NOT NULL DEFAULT 1 CHECK (attempt_number > 0),
                                                request_headers jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(request_headers) = 'object'),
                                                response_status integer CHECK (response_status IS NULL OR response_status BETWEEN 100 AND 599),
                                                response_headers jsonb,
                                                response_body_excerpt text,
                                                status text NOT NULL DEFAULT 'PENDING'
                                                    CHECK (status IN ('PENDING', 'SENDING', 'SUCCEEDED', 'FAILED', 'DEAD')),
                                                next_attempt_at timestamptz,
                                                started_at timestamptz,
                                                completed_at timestamptz,
                                                duration_ms integer CHECK (duration_ms IS NULL OR duration_ms >= 0),
                                                error_message text,
                                                PRIMARY KEY (tenant_id, created_at, id),
                                                FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                                FOREIGN KEY (tenant_id, subscription_id)
                                                    REFERENCES integration.webhook_subscriptions(tenant_id, id) ON DELETE CASCADE,
                                                CHECK (completed_at IS NULL OR started_at IS NULL OR completed_at >= started_at)
) PARTITION BY RANGE (created_at);

CREATE INDEX idx_webhook_deliveries_retry
    ON integration.webhook_deliveries (tenant_id, status, next_attempt_at)
    WHERE status IN ('PENDING', 'FAILED');
CREATE INDEX idx_webhook_deliveries_subscription
    ON integration.webhook_deliveries (tenant_id, subscription_id, created_at DESC);
CREATE INDEX idx_webhook_deliveries_brin_time
    ON integration.webhook_deliveries USING brin (created_at);

CREATE TABLE integration.idempotency_keys (
                                              tenant_id uuid NOT NULL,
                                              idempotency_key text NOT NULL,
                                              operation_scope text NOT NULL,
                                              request_hash text NOT NULL,
                                              response_status integer,
                                              response_body jsonb,
                                              resource_type text,
                                              resource_id uuid,
                                              locked_until timestamptz,
                                              created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                              expires_at timestamptz NOT NULL,
                                              PRIMARY KEY (tenant_id, operation_scope, idempotency_key),
                                              FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                              CHECK (expires_at > created_at)
);

CREATE INDEX idx_idempotency_keys_expiry
    ON integration.idempotency_keys (expires_at);

CREATE TABLE integration.import_jobs (
                                         tenant_id uuid NOT NULL,
                                         id uuid NOT NULL DEFAULT gen_random_uuid(),
                                         job_type text NOT NULL,
                                         source_type text NOT NULL
                                             CHECK (source_type IN ('CSV', 'XLSX', 'API', 'CONNECTOR', 'OTHER')),
                                         source_reference text,
                                         target_entity_type text NOT NULL,
                                         status text NOT NULL DEFAULT 'PENDING'
                                             CHECK (status IN ('PENDING', 'VALIDATING', 'RUNNING', 'COMPLETED', 'COMPLETED_WITH_ERRORS', 'FAILED', 'CANCELLED')),
                                         total_rows bigint CHECK (total_rows IS NULL OR total_rows >= 0),
                                         processed_rows bigint NOT NULL DEFAULT 0 CHECK (processed_rows >= 0),
                                         success_rows bigint NOT NULL DEFAULT 0 CHECK (success_rows >= 0),
                                         error_rows bigint NOT NULL DEFAULT 0 CHECK (error_rows >= 0),
                                         mapping_config jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(mapping_config) = 'object'),
                                         error_report_reference text,
                                         started_at timestamptz,
                                         completed_at timestamptz,
                                         requested_by uuid,
                                         created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                         updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                         created_by uuid,
                                         updated_by uuid,
                                         version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
                                         PRIMARY KEY (tenant_id, id),
                                         FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                         FOREIGN KEY (tenant_id, requested_by)
                                             REFERENCES platform.tenant_memberships(tenant_id, user_id) ON DELETE SET NULL (requested_by),
                                         CHECK (completed_at IS NULL OR started_at IS NULL OR completed_at >= started_at),
                                         CHECK (success_rows + error_rows <= processed_rows),
                                         CHECK (total_rows IS NULL OR processed_rows <= total_rows)
);

CREATE INDEX idx_import_jobs_status
    ON integration.import_jobs (tenant_id, status, created_at DESC);

-- --------------------------------------------------------------------------
-- Audit: append-only change and access trails
-- --------------------------------------------------------------------------

CREATE TABLE audit.audit_events (
                                    tenant_id uuid NOT NULL,
                                    occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                    id uuid NOT NULL DEFAULT gen_random_uuid(),
                                    schema_name text NOT NULL,
                                    table_name text NOT NULL,
                                    aggregate_type text NOT NULL,
                                    aggregate_id uuid,
                                    action text NOT NULL CHECK (action IN ('INSERT', 'UPDATE', 'DELETE')),
  changed_fields jsonb NOT NULL DEFAULT '[]'::jsonb
    CHECK (jsonb_typeof(changed_fields) = 'array'),
  old_values jsonb,
  new_values jsonb,
  actor_user_id uuid,
  actor_type text NOT NULL DEFAULT 'USER'
    CHECK (actor_type IN ('USER', 'SYSTEM', 'INTEGRATION', 'SUPPORT')),
  request_id uuid,
  correlation_id uuid,
  source_ip inet,
  user_agent text,
  application_name text,
  PRIMARY KEY (tenant_id, occurred_at, id),
  FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
  FOREIGN KEY (tenant_id, actor_user_id)
    REFERENCES platform.tenant_memberships(tenant_id, user_id)
    ON DELETE SET NULL (actor_user_id)
) PARTITION BY RANGE (occurred_at);

CREATE INDEX idx_audit_events_aggregate
    ON audit.audit_events (tenant_id, aggregate_type, aggregate_id, occurred_at DESC);
CREATE INDEX idx_audit_events_actor
    ON audit.audit_events (tenant_id, actor_user_id, occurred_at DESC)
    WHERE actor_user_id IS NOT NULL;
CREATE INDEX idx_audit_events_request
    ON audit.audit_events (tenant_id, request_id)
    WHERE request_id IS NOT NULL;
CREATE INDEX idx_audit_events_brin_time
    ON audit.audit_events USING brin (occurred_at);

CREATE TABLE audit.data_access_events (
                                          tenant_id uuid NOT NULL,
                                          occurred_at timestamptz NOT NULL DEFAULT clock_timestamp(),
                                          id uuid NOT NULL DEFAULT gen_random_uuid(),
                                          entity_type text NOT NULL,
                                          entity_id uuid,
                                          access_type text NOT NULL
                                              CHECK (access_type IN ('VIEW', 'EXPORT', 'DOWNLOAD', 'SEARCH', 'DECRYPT')),
                                          fields_accessed text[] NOT NULL DEFAULT ARRAY[]::text[],
                                          actor_user_id uuid,
                                          actor_type text NOT NULL DEFAULT 'USER'
                                              CHECK (actor_type IN ('USER', 'SYSTEM', 'INTEGRATION', 'SUPPORT')),
                                          purpose text,
                                          legal_basis text,
                                          request_id uuid,
                                          source_ip inet,
                                          user_agent text,
                                          metadata jsonb NOT NULL DEFAULT '{}'::jsonb
    CHECK (jsonb_typeof(metadata) = 'object'),
                                          PRIMARY KEY (tenant_id, occurred_at, id),
                                          FOREIGN KEY (tenant_id) REFERENCES platform.tenants(id) ON DELETE CASCADE,
                                          FOREIGN KEY (tenant_id, actor_user_id)
                                              REFERENCES platform.tenant_memberships(tenant_id, user_id)
                                              ON DELETE SET NULL (actor_user_id)
) PARTITION BY RANGE (occurred_at);

CREATE INDEX idx_data_access_entity
    ON audit.data_access_events (tenant_id, entity_type, entity_id, occurred_at DESC);
CREATE INDEX idx_data_access_actor
    ON audit.data_access_events (tenant_id, actor_user_id, occurred_at DESC)
    WHERE actor_user_id IS NOT NULL;
CREATE INDEX idx_data_access_brin_time
    ON audit.data_access_events USING brin (occurred_at);

CREATE OR REPLACE FUNCTION audit.redact_jsonb(p_value jsonb)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
PARALLEL SAFE
AS $$
SELECT CASE
           WHEN p_value IS NULL THEN NULL
           ELSE p_value - ARRAY[
               'password', 'password_hash', 'access_token', 'refresh_token',
               'api_key', 'client_secret', 'secret', 'secret_reference',
               'signature', 'private_key', 'bank_account_number', 'search_vector'
               ]::text[]
           END
           $$;

CREATE OR REPLACE FUNCTION audit.log_row_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, audit, platform
AS $$
DECLARE
v_old jsonb;
  v_new jsonb;
  v_tenant_id uuid;
  v_aggregate_id uuid;
  v_changed_fields jsonb := '[]'::jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_new := audit.redact_jsonb(to_jsonb(NEW));
    v_tenant_id := NULLIF(v_new ->> 'tenant_id', '')::uuid;
    v_aggregate_id := NULLIF(v_new ->> 'id', '')::uuid;
  ELSIF TG_OP = 'UPDATE' THEN
    v_old := audit.redact_jsonb(to_jsonb(OLD));
    v_new := audit.redact_jsonb(to_jsonb(NEW));
    v_tenant_id := COALESCE(
      NULLIF(v_new ->> 'tenant_id', '')::uuid,
      NULLIF(v_old ->> 'tenant_id', '')::uuid
    );
    v_aggregate_id := COALESCE(
      NULLIF(v_new ->> 'id', '')::uuid,
      NULLIF(v_old ->> 'id', '')::uuid
    );

SELECT COALESCE(jsonb_agg(key ORDER BY key), '[]'::jsonb)
INTO v_changed_fields
FROM (
         SELECT key
         FROM jsonb_object_keys(COALESCE(v_old, '{}'::jsonb) || COALESCE(v_new, '{}'::jsonb)) AS keys(key)
         WHERE v_old -> key IS DISTINCT FROM v_new -> key
             AND key NOT IN ('updated_at', 'updated_by', 'version', 'search_vector')
     ) changed;
ELSE
    v_old := audit.redact_jsonb(to_jsonb(OLD));
    v_tenant_id := NULLIF(v_old ->> 'tenant_id', '')::uuid;
    v_aggregate_id := NULLIF(v_old ->> 'id', '')::uuid;
END IF;

  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'Audit trigger requires tenant_id on %.%', TG_TABLE_SCHEMA, TG_TABLE_NAME;
END IF;

INSERT INTO audit.audit_events (
    tenant_id,
    schema_name,
    table_name,
    aggregate_type,
    aggregate_id,
    action,
    changed_fields,
    old_values,
    new_values,
    actor_user_id,
    actor_type,
    request_id,
    application_name
)
VALUES (
           v_tenant_id,
           TG_TABLE_SCHEMA,
           TG_TABLE_NAME,
           TG_TABLE_SCHEMA || '.' || TG_TABLE_NAME,
           v_aggregate_id,
           TG_OP,
           v_changed_fields,
           v_old,
           v_new,
           platform.current_actor_user_id(),
           COALESCE(NULLIF(current_setting('app.actor_type', true), ''), 'USER'),
           platform.current_request_id(),
           current_setting('application_name', true)
       );

IF TG_OP = 'DELETE' THEN
    RETURN OLD;
END IF;
RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION audit.log_data_access(
  p_entity_type text,
  p_entity_id uuid,
  p_access_type text,
  p_fields_accessed text[] DEFAULT ARRAY[]::text[],
  p_purpose text DEFAULT NULL,
  p_legal_basis text DEFAULT NULL,
  p_metadata jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, audit, platform
AS $$
DECLARE
v_id uuid := gen_random_uuid();
BEGIN
INSERT INTO audit.data_access_events (
    tenant_id,
    id,
    entity_type,
    entity_id,
    access_type,
    fields_accessed,
    actor_user_id,
    actor_type,
    purpose,
    legal_basis,
    request_id,
    metadata
)
VALUES (
           platform.current_tenant_id(),
           v_id,
           p_entity_type,
           p_entity_id,
           p_access_type,
           COALESCE(p_fields_accessed, ARRAY[]::text[]),
           platform.current_actor_user_id(),
           COALESCE(NULLIF(current_setting('app.actor_type', true), ''), 'USER'),
           p_purpose,
           p_legal_basis,
           platform.current_request_id(),
           COALESCE(p_metadata, '{}'::jsonb)
       );

RETURN v_id;
END;
$$;

-- --------------------------------------------------------------------------
-- Monthly partition management for append/event tables
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION common.ensure_month_partition(
  p_parent_table regclass,
  p_partition_month date
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, common
AS $$
DECLARE
v_parent_schema text;
  v_parent_name text;
  v_parent_kind "char";
  v_start timestamptz;
  v_end timestamptz;
  v_partition_name text;
  v_qualified_partition text;
BEGIN
SELECT n.nspname, c.relname, c.relkind
INTO v_parent_schema, v_parent_name, v_parent_kind
FROM pg_class c
         JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.oid = p_parent_table;

IF v_parent_name IS NULL OR v_parent_kind <> 'p' THEN
    RAISE EXCEPTION '% is not a partitioned table', p_parent_table;
END IF;

  v_start := date_trunc('month', p_partition_month::timestamptz);
  v_end := v_start + interval '1 month';
  v_partition_name := v_parent_name || '_' || to_char(v_start, 'YYYYMM');
  v_qualified_partition := format('%I.%I', v_parent_schema, v_partition_name);

EXECUTE format(
        'CREATE TABLE IF NOT EXISTS %I.%I PARTITION OF %I.%I FOR VALUES FROM (%L) TO (%L)',
        v_parent_schema,
        v_partition_name,
        v_parent_schema,
        v_parent_name,
        v_start,
        v_end
        );

EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', v_parent_schema, v_partition_name);
EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', v_parent_schema, v_partition_name);

IF NOT EXISTS (
    SELECT 1
    FROM pg_policies
    WHERE schemaname = v_parent_schema
      AND tablename = v_partition_name
      AND policyname = 'tenant_isolation'
  ) THEN
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I.%I USING (tenant_id = platform.current_tenant_id()) WITH CHECK (tenant_id = platform.current_tenant_id())',
      v_parent_schema,
      v_partition_name
    );
END IF;

RETURN v_qualified_partition;
END;
$$;

DO $$
DECLARE
v_offset integer;
  v_month date;
  v_parent regclass;
BEGIN
  FOREACH v_parent IN ARRAY ARRAY[
    'service.ticket_events'::regclass,
    'integration.outbox_events'::regclass,
    'integration.webhook_deliveries'::regclass,
    'audit.audit_events'::regclass,
    'audit.data_access_events'::regclass
  ]
  LOOP
    FOR v_offset IN -1..18 LOOP
      v_month := (date_trunc('month', current_date) + make_interval(months => v_offset))::date;
      PERFORM common.ensure_month_partition(v_parent, v_month);
END LOOP;
END LOOP;
END;
$$;

CREATE TABLE service.ticket_events_default
    PARTITION OF service.ticket_events DEFAULT;
CREATE TABLE integration.outbox_events_default
    PARTITION OF integration.outbox_events DEFAULT;
CREATE TABLE integration.webhook_deliveries_default
    PARTITION OF integration.webhook_deliveries DEFAULT;
CREATE TABLE audit.audit_events_default
    PARTITION OF audit.audit_events DEFAULT;
CREATE TABLE audit.data_access_events_default
    PARTITION OF audit.data_access_events DEFAULT;

COMMENT ON FUNCTION common.ensure_month_partition(regclass, date) IS
  'Create a monthly partition. Schedule this before each future month; the default partition is a safety net, not the intended steady-state target.';

-- --------------------------------------------------------------------------
-- Automatic updated_at/version triggers
-- --------------------------------------------------------------------------

DO $$
DECLARE
r record;
BEGIN
FOR r IN
SELECT n.nspname AS schema_name, c.relname AS table_name
FROM pg_class c
         JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind = 'r'
  AND NOT c.relispartition
  AND n.nspname IN (
                    'platform', 'crm', 'catalog', 'sales', 'marketing',
                    'service', 'privacy', 'integration'
    )
  AND EXISTS (
    SELECT 1 FROM pg_attribute a
    WHERE a.attrelid = c.oid AND a.attname = 'updated_at' AND NOT a.attisdropped
)
  AND EXISTS (
    SELECT 1 FROM pg_attribute a
    WHERE a.attrelid = c.oid AND a.attname = 'updated_by' AND NOT a.attisdropped
)
  AND EXISTS (
    SELECT 1 FROM pg_attribute a
    WHERE a.attrelid = c.oid AND a.attname = 'version' AND NOT a.attisdropped
)
    LOOP
    EXECUTE format(
      'CREATE TRIGGER trg_touch_row BEFORE UPDATE ON %I.%I FOR EACH ROW EXECUTE FUNCTION common.touch_row()',
      r.schema_name,
      r.table_name
    );
END LOOP;
END;
$$;

-- --------------------------------------------------------------------------
-- Change-audit triggers on business-critical mutable aggregates
-- --------------------------------------------------------------------------

DO $$
DECLARE
r record;
BEGIN
FOR r IN
SELECT * FROM (VALUES
                   ('platform', 'tenant_memberships'),
                   ('platform', 'teams'),
                   ('platform', 'roles'),
                   ('crm', 'accounts'),
                   ('crm', 'contacts'),
                   ('crm', 'communication_channels'),
                   ('crm', 'leads'),
                   ('crm', 'opportunities'),
                   ('crm', 'activities'),
                   ('crm', 'notes'),
                   ('crm', 'custom_field_definitions'),
                   ('crm', 'custom_field_values'),
                   ('catalog', 'products'),
                   ('catalog', 'price_books'),
                   ('sales', 'quotes'),
                   ('sales', 'orders'),
                   ('sales', 'contracts'),
                   ('marketing', 'campaigns'),
                   ('service', 'tickets'),
                   ('service', 'ticket_comments'),
                   ('privacy', 'consents'),
                   ('privacy', 'data_subject_requests'),
                   ('integration', 'webhook_subscriptions')
              ) AS audited(schema_name, table_name)
    LOOP
    EXECUTE format(
      'CREATE TRIGGER trg_audit_row AFTER INSERT OR UPDATE OR DELETE ON %I.%I FOR EACH ROW EXECUTE FUNCTION audit.log_row_change()',
      r.schema_name,
      r.table_name
    );
END LOOP;
END;
$$;

-- --------------------------------------------------------------------------
-- Row-Level Security: deny by default without app.tenant_id
-- --------------------------------------------------------------------------

ALTER TABLE platform.tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE platform.tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_self
  ON platform.tenants
  USING (id = platform.current_tenant_id())
  WITH CHECK (id = platform.current_tenant_id());

DO $$
DECLARE
r record;
BEGIN
FOR r IN
SELECT n.nspname AS schema_name, c.relname AS table_name
FROM pg_class c
         JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind IN ('r', 'p')
  AND n.nspname IN (
                    'platform', 'crm', 'catalog', 'sales', 'marketing',
                    'service', 'privacy', 'integration', 'audit'
    )
  AND EXISTS (
    SELECT 1
    FROM pg_attribute a
    WHERE a.attrelid = c.oid
      AND a.attname = 'tenant_id'
      AND NOT a.attisdropped
)
    LOOP
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', r.schema_name, r.table_name);
EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', r.schema_name, r.table_name);

IF NOT EXISTS (
      SELECT 1
      FROM pg_policies p
      WHERE p.schemaname = r.schema_name
        AND p.tablename = r.table_name
        AND p.policyname = 'tenant_isolation'
    ) THEN
      EXECUTE format(
        'CREATE POLICY tenant_isolation ON %I.%I USING (tenant_id = platform.current_tenant_id()) WITH CHECK (tenant_id = platform.current_tenant_id())',
        r.schema_name,
        r.table_name
      );
END IF;
END LOOP;
END;
$$;

-- --------------------------------------------------------------------------
-- Public privilege hardening
-- --------------------------------------------------------------------------

REVOKE ALL ON SCHEMA common, platform, crm, catalog, sales, marketing,
    service, privacy, integration, audit FROM PUBLIC;

REVOKE ALL ON ALL TABLES IN SCHEMA platform, crm, catalog, sales, marketing,
    service, privacy, integration, audit FROM PUBLIC;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA common, platform, crm, catalog, sales,
    marketing, service, privacy, integration, audit FROM PUBLIC;

ALTER DEFAULT PRIVILEGES REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES REVOKE ALL ON FUNCTIONS FROM PUBLIC;

-- Application role grants should be performed by a separate environment-specific
-- migration, for example:
--   GRANT USAGE ON SCHEMA platform, crm, catalog, sales, marketing,
--     service, privacy, integration, audit TO crm_app;
--   GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA
--     platform, crm, catalog, sales, marketing, service, privacy,
--     integration TO crm_app;
--   GRANT SELECT, INSERT ON ALL TABLES IN SCHEMA audit TO crm_app;
--   GRANT EXECUTE ON FUNCTION platform.current_tenant_id() TO crm_app;
--   GRANT EXECUTE ON FUNCTION platform.current_actor_user_id() TO crm_app;
--   GRANT EXECUTE ON FUNCTION platform.current_request_id() TO crm_app;
--   GRANT EXECUTE ON FUNCTION platform.set_request_context(uuid, uuid, uuid) TO crm_app;
--   GRANT EXECUTE ON FUNCTION audit.log_data_access(text, uuid, text, text[], text, text, jsonb) TO crm_app;

COMMENT ON TABLE crm.accounts IS 'Customer organizations/person accounts. Composite tenant key prevents cross-tenant references.';
COMMENT ON TABLE crm.contacts IS 'Natural persons associated with zero or one primary account.';
COMMENT ON TABLE crm.leads IS 'Unqualified or pre-conversion prospects; conversion links preserve source history.';
COMMENT ON TABLE crm.opportunities IS 'Pipeline opportunities with configurable stages and immutable stage history.';
COMMENT ON TABLE sales.quote_items IS 'Quote-line product and pricing snapshots; historical documents do not change with the catalog.';
COMMENT ON TABLE privacy.consents IS 'Append-oriented consent evidence by subject, channel, purpose, lawful basis, and policy version.';
COMMENT ON TABLE integration.outbox_events IS 'Transactional outbox. Insert in the same transaction as the aggregate change.';
COMMENT ON TABLE audit.audit_events IS 'Append-only row-change audit trail with common secret fields removed.';

COMMIT;

